    // ═══════════════════════════════════════════════════════════
    // STORY 37 — Heart of Darkness (Joseph Conrad)
    // ═══════════════════════════════════════════════════════════
    private fun story37() = StoryContent(
        storyId = "adv_heart_of_darkness",
        chapters = listOf(
            StoryChapter(
                number = 1, title = "The Thames", titlePersian = "تیمز",
                paragraphs = listOf(
                    StoryParagraph("The Nellie, a cruising yawl, swung to her anchor without a flutter of the sails, and was at rest on the wide expanse of the Thames estuary, where the water stretched toward the open sea like a gray and silent road leading into the unknown.", "نِلی، یک قایق تفریحی بادبانی، بدون تکان خوردن بادبان‌ها بر لنگرش تاب می‌خورد و در گستره وسیع دهانه تیمز آرام گرفته بود، جایی که آب مثل جاده‌ای خاکستری و ساکت که به ناشناخته‌ها منتهی می‌شد، به سمت دریای آزاد کشیده شده بود."),
                    StoryParagraph("The tide was at rest, the wind was nearly calm, and only the faintest ripple disturbed the surface of the river, so that the whole scene seemed suspended between day and night, between the known world and the vast emptiness beyond.", "جزر و مد آرام بود، باد تقریباً ساکن و تنها موج‌های بسیار ضعیفی سطح رودخانه را می‌آشفت، طوری که تمام منظره میان روز و شب معلق به نظر می‌رسید، میان جهان شناخته‌شده و تهی‌بودن گسترده فراتر از آن."),
                    StoryParagraph("On board the Nellie were five men, friends gathered for an evening of talk and memories, men who had known the sea in different ways and who now shared the quiet companionship of the river and the fading light.", "پنج مرد بر نلی سوار بودند، دوستانی که برای شبی از گفتگو و خاطرات گرد آمده بودند، مردانی که دریا را به شیوه‌های مختلف می‌شناختند و اکنون همراهی آرام رودخانه و نور محو شونده را با هم قسمت می‌کردند."),
                    StoryParagraph("Among them was Charles Marlow, a seaman who had spent his life on the sea, a wanderer who had sailed to every corner of the world but who carried within him a restless curiosity that no voyage had ever fully satisfied.", "در میان آن‌ها چارلز مارلو بود، دریانوردی که عمرش را بر دریا گذرانده بود، سرگردانی که به هر گوشه جهان سفر کرده بود اما در درونش کنجکاوی بی‌قراری حمل می‌کرد که هیچ سفری هرگز به‌طور کامل راضی‌اش نکرده بود."),
                    StoryParagraph("Marlow was different from the others, for he did not tell simple stories with clear morals and neat endings, but rather spoke in a way that seemed to circle around the truth without ever quite capturing it.", "مارلو با دیگران متفاوت بود، چون داستان‌های ساده با درس‌های روشن و پایان‌های مرتب تعریف نمی‌کرد، بلکه به شیوه‌ای سخن می‌گفت که به نظر می‌رسید گرد حقیقت می‌چرخد بدون اینکه هرگز کاملاً آن را به چنگ آورد."),
                    StoryParagraph("To him, the meaning of a story was not inside like a kernel but outside, enveloping the tale which brought it out only as a glow brings out a haze, in the likeness of one of those misty halos that sometimes are made visible by the spectral illumination of moonshine.", "برای او، معنای داستان درونش مثل مغز نبود، بلکه بیرونش بود، احاطه‌کننده‌اش، که داستان را تنها همان‌گونه بیرون می‌کشد که درخششی مه را، به شباهت یکی از آن هاله‌های مه‌آلود که گاهی با نور شبح‌وار مهتاب مرئی می‌شوند."),
                    StoryParagraph("As the sun set over London and the great city began to light its lamps along the shore, Marlow began to speak of a journey he had made years before, a journey that had marked him forever and that he had never been able to forget.", "هنگامی که خورشید بر لندن غروب می‌کرد و شهر بزرگ شروع به روشن کردن چراغ‌هایش در کنار ساحل می‌کرد، مارلو شروع به سخن گفتن از سفری کرد که سال‌ها پیش کرده بود، سفری که برای همیشه او را نشانه گذاشته بود و هرگز نتوانسته بود فراموشش کند."),
                    StoryParagraph("It was a journey into the heart of Africa, into the darkness of the Congo River, a journey that would take him from the comfortable certainties of European civilization into the primal chaos of a land that had no name in his language.", "سفری بود به قلب آفریقا، به تاریکی رود کنگو، سفری که او را از یقین‌های راحت تمدن اروپایی به آشوب نخستین سرزمینی می‌برد که در زبانش نامی نداشت."),
                    StoryParagraph("I was thinking of very old times, he said, when the Romans first came here to Britain, nineteen hundred years ago, and the light of civilization had not yet touched these shores, and this too was one of the dark places of the earth.", "او گفت به زمان‌های بسیار کهن فکر می‌کردم، وقتی رومیان نخستین بار به اینجا، بریتانیا، نوزده قرن پیش آمدند و نور تمدن هنوز این سواحل را لمس نکرده بود و این نیز یکی از مکان‌های تاریک زمین بود."),
                    StoryParagraph("They came to a land of marshes and forests and savages, and they brought with them what they called civilization, but which was often only a thin veneer over the darkness that lay within every human heart.", "آن‌ها به سرزمینی از باتلاق‌ها و جنگل‌ها و وحشی‌ها آمدند و آنچه تمدن می‌نامیدند با خود آوردند، اما اغلب تنها پوسته‌ای نازک بود بر تاریکی که در قلب هر انسانی جای داشت."),
                    StoryParagraph("Here and there a military camp lost in a wilderness, like a needle in a bundle of hay, cold, fog, tempests, disease, exile, and death, death skulking in the air, in the water, in the bush, they were dying in the midst of it.", "اینجا و آنجا اردوگاهی نظامی گمشده در بیابان، مثل سوزنی در بسته‌ای از کاه، سرما، مه، طوفان، بیماری، تبعید و مرگ، مرگی که در هوا، در آب، در بوته‌ها پرسه می‌زد، آن‌ها در میانش می‌مردند."),
                    StoryParagraph("This also has been one of the dark places of the earth, Marlow said, and he paused, and the men on the Nellie looked at him in silence, knowing that he was about to take them somewhere far away.", "مارلو گفت این نیز یکی از مکان‌های تاریک زمین بوده است، و مکث کرد، و مردان روی نلی در سکوت به او نگاه کردند، می‌دانستند که او می‌خواهد آنان را به جایی دور ببرد."),
                    StoryParagraph("He spoke of the great river, the Congo, which he had once traveled as a steamboat captain, a river of immense power that wound through jungles and swamps and villages, a river that seemed to hold within its dark waters the secrets of all human history.", "او از رود بزرگ کنگو سخن گفت، که روزی به‌عنوان ناخدای قایق بخار در آن سفر کرده بود، رودی با قدرتی عظیم که از میان جنگل‌ها و باتلاق‌ها و دهکده‌ها می‌پیچید، رودی که به نظر می‌رسید در آب‌های تاریکش رازهای تمام تاریخ بشری را در خود جای داده است."),
                    StoryParagraph("I have been to the Congo, Marlow said, and I have seen what men do to other men when they are given power without restraint and wealth without conscience, when the only law is the law of profit and the only god is the god of ivory.", "مارلو گفت من به کنگو رفته‌ام و دیده‌ام مردان با مردان دیگر چه می‌کنند وقتی به آنان قدرت بی‌قید و ثروت بی‌وجدان داده می‌شود، وقتی تنها قانون، قانون سود است و تنها خدا، خدای عاج."),
                    StoryParagraph("The men on the Nellie listened in silence, for they could feel the weight of his words, and they knew that he was not merely telling a story but confessing something that had changed him forever.", "مردان روی نلی در سکوت گوش دادند، زیرا می‌توانستند سنگینی کلماتش را حس کنند و می‌دانستند که او تنها داستانی تعریف نمی‌کند بلکه به چیزی اعتراف می‌کند که او را برای همیشه تغییر داده بود."),
                    StoryParagraph("Marlow told them of the Company, a Belgian trading company that ruled the Congo with an iron hand, and whose only interest was the extraction of ivory from the interior of the vast and mysterious continent.", "مارلو برایشان از کمپانی گفت، شرکت تجاری بلژیکی که با دستی آهنین بر کنگو حکومت می‌کرد و تنها علاقه‌اش استخراج عاج از درون قاره وسیع و مرموز بود."),
                    StoryParagraph("The Company was not in Africa for civilization, not for the enlightenment of the natives, not for the glory of God, but for ivory, for profit, for the enrichment of a few men in Brussels who had never set foot on African soil.", "کمپانی برای تمدن در آفریقا نبود، نه برای روشنگری بومیان، نه برای جلال خدا، بلکه برای عاج، برای سود، برای ثروتمند شدن چند مرد در بروکسل که هرگز پا بر خاک آفریقا نگذاشته بودند."),
                    StoryParagraph("They had heard of a man named Kurtz, the best agent in the whole territory, a man who was said to have collected more ivory than all the other agents combined, a man whose name was spoken with reverence and with fear.", "آن‌ها از مردی به نام کورتز شنیده بودند، بهترین مأمور در تمام قلمرو، مردی که می‌گفتند بیشتر از همه مأموران دیگر با هم عاج جمع کرده است، مردی که نامش با احترام و با ترس برده می‌شد."),
                    StoryParagraph("Kurtz was an idealist, a man of great talent and great ambition, a man who had come to Africa to bring light to the darkness, or so he had claimed in his reports to the Company, but who had become something else entirely.", "کورتز آرمان‌گرایی بود، مردی با استعداد فراوان و جاه‌طلبی فراوان، مردی که به آفریقا آمده بود تا نور به تاریکی بیاورد، یا اینگونه در گزارش‌هایش به کمپانی ادعا کرده بود، اما به چیزی کاملاً متفاوت تبدیل شده بود."),
                    StoryParagraph("He was said to have collected more ivory than all the other agents combined, and to have established himself as the master of a tribe that worshipped him as a god, and the rumors of what he had become were whispered with a mixture of awe and horror.", "می‌گفتند بیشتر از همه مأموران دیگر با هم عاج جمع کرده و خود را رئیس قبیله‌ای کرده که او را همچون خدا می‌پرستیدند، و شایعات درباره آنچه شده بود با ترکیبی از هیبت و وحشت زمزمه می‌شد."),
                    StoryParagraph("But he had also gone mad, or so the rumors said, and he had become the master of a tribe that worshipped him as a god, and the Company was worried that he had forgotten his duty to them.", "اما دیوانه هم شده بود، یا شایعات چنین می‌گفتند، و رئیس قبیله‌ای شده بود که او را همچون خدا می‌پرستیدند، و کمپانی نگران بود که او وظیفه‌اش به آن‌ها را فراموش کرده باشد."),
                    StoryParagraph("Marlow was hired by the Company to travel up the river and bring Kurtz back, a task that seemed simple enough at the time but that would turn out to be the most difficult and terrible journey of his life.", "مارلو توسط کمپانی استخدام شد تا در رود سفر کند و کورتز را بازگرداند، وظیفه‌ای که آن موقع به اندازه کافی ساده به نظر می‌رسید اما به دشوارترین و هولناک‌ترین سفر زندگی‌اش تبدیل شد."),
                    StoryParagraph("It seemed to be a simple task, but Marlow soon learned that nothing in the Congo was simple, and that the darkness he would encounter was not only in the land but in the hearts of the men who had come to conquer it.", "به نظر وظیفه ساده‌ای می‌آمد، اما مارلو به‌زودی آموخت هیچ چیز در کنگو ساده نیست و تاریکی‌ای که با آن روبرو می‌شد نه تنها در سرزمین بود بلکه در قلب مردانی بود که برای فتحش آمده بودند."),
                    StoryParagraph("He traveled first to Brussels, the headquarters of the Company, a city he found cold and unnatural, a city of white sepulchers where the talk was all of profit and the only god was the god of money.", "او نخست به بروکسل رفت، مرکز کمپانی، شهری که سرد و غیرطبیعی یافت، شهری از آرامگاه‌های سفید که در آن صحبت همه از سود بود و تنها خدا، خدای پول."),
                    StoryParagraph("In the Company office, two women in black sat knitting, as if at a funeral, guardians of the door of Darkness, and they did not speak, and their silence seemed to Marlow more terrible than any words could be.", "در دفتر کمپانی، دو زن سیاه‌پوش نشسته بودند و بافتنی می‌بافتند، گویی در مراسم ختم، نگهبانان دروازه تاریکی، و سخن نمی‌گفتند، و سکوتشان به نظر مارلو هولناک‌تر از هر کلمه‌ای بود."),
                    StoryParagraph("Marlow was examined by a doctor who measured his head with a strange instrument and asked if he had any madness in his family, which Marlow found disturbing, as if madness were a thing that could be inherited like a disease.", "مارلو توسط پزشکی معاینه شد که سرش را با ابزاری عجیب اندازه گرفت و پرسید آیا در خانواده‌اش جنونی هست، که مارلو آن را نگران‌کننده یافت، گویی جنون چیزی است که مثل بیماری به ارث می‌رسد."),
                    StoryParagraph("He then boarded a French steamer that would take him to the mouth of the Congo, and as the ship moved down the coast, Marlow watched the African shoreline pass by and felt that he was leaving behind everything he had ever known.", "سپس سوار کشتی بخار فرانسوی شد که او را به دهانه کنگو می‌برد، و هنگامی که کشتی در امتداد ساحل پیش می‌رفت، مارلو تماشا کرد که ساحل آفریقا از کنارش می‌گذرد و حس کرد که همه چیزی که تا به حال می‌شناخته را پشت سر می‌گذارد."),
                    StoryParagraph("It was a land of great mystery, and it seemed to look back at him with a strange familiarity, as if it recognized him, as if it knew something about him that he did not yet know about himself.", "سرزمینی پر از رمز و راز بود و به نظر می‌رسید با آشنایی غریب به او بازمی‌نگرد، گویی او را می‌شناسد، گویی چیزی درباره‌اش می‌داند که او هنوز درباره خودش نمی‌داند."),
                    StoryParagraph("And so began Marlow's journey into the heart of darkness, a journey that would strip away all his illusions about civilization and progress and the goodness of man.", "و اینگونه سفر مارلو به قلب تاریکی آغاز شد، سفری که تمام توهماتش درباره تمدن و پیشرفت و خوبی انسان را برهنه می‌کرد."),
                    StoryParagraph("A journey that would teach him that the darkness is not out there, in the heart of Africa, but in here, in the heart of every human being, waiting to be unleashed.", "سفری که به او می‌آموخت تاریکی آن بیرون نیست، در قلب آفریقا، بلکه اینجاست، در قلب هر انسانی، منتظر آزاد شدن."),
                    StoryParagraph("And it was this lesson, more than anything else, that would haunt him for the rest of his life.", "و این درس، بیش از هر چیز دیگری، بود که باقی عمرش را تعقیب می‌کرد."),
                    StoryParagraph("For once you have seen the darkness in your own heart, you can never again believe yourself innocent.", "زیرا هنگامی که تاریکی قلب خودت را دیده باشی، دیگر هرگز نمی‌توانی خودت را معصوم بدانی."),
                    StoryParagraph("And so ended the first part of Marlow's tale, with the sun setting over London and the darkness gathering on the river.", "و اینگونه بخش نخست داستان مارلو با غروب خورشید بر لندن و تجمع تاریکی بر رود به پایان رسید.")
                )
            ),
            StoryChapter(
                number = 2, title = "The Company Station", titlePersian = "ایستگاه کمپانی",
                paragraphs = listOf(
                    StoryParagraph("Marlow arrived at the Company station after a long and difficult journey up the coast, and what he saw there would remain with him for the rest of his life, a vision of human degradation that no words could fully convey.", "مارلو پس از سفری طولانی و دشوار در امتداد ساحل به ایستگاه کمپانی رسید و آنچه آنجا دید باقی عمرش با او می‌ماند، تصویری از انحطاط انسانی که هیچ کلمه‌ای نمی‌توانست کاملاً منتقلش کند."),
                    StoryParagraph("The station was a place of chaos and neglect, a collection of buildings that seemed to have been thrown together without plan or purpose, surrounded by a wilderness that pressed in from all sides.", "ایستگاه جایی از آشوب و بی‌توجهی بود، مجموعه‌ای از ساختمان‌ها که به نظر می‌رسید بدون نقشه یا هدفی سرهم شده‌اند، احاطه شده با بیابانی که از همه طرف فشار می‌آورد."),
                    StoryParagraph("He saw black men, chained together, walking in a line, carrying baskets of earth on their heads, their bodies thin and wasted, their eyes empty of all hope, their movements mechanical and lifeless.", "او مردان سیاهی را دید، به هم زنجیر شده، در یک خط راه می‌رفتند، سبدهای خاک بر سرشان حمل می‌کردند، بدن‌هایشان لاغر و تباه، چشمانشان خالی از هر امیدی، حرکاتشان مکانیکی و بی‌جان."),
                    StoryParagraph("They were not men to the Company, they were not even animals, they were simply tools, instruments of labor to be used until they broke and then discarded like so much refuse on the side of the road.", "آن‌ها برای کمپانی انسان نبودند، حتی حیوان هم نبودند، آن‌ها تنها ابزار بودند، ابزار کار که تا شکستن استفاده می‌شدند و بعد مثل آشغال در کنار جاده دور انداخته می‌شدند."),
                    StoryParagraph("Marlow saw a group of these men resting in the shade of a tree, so thin and so exhausted that they seemed more dead than alive, and he saw that one of them, a young boy, had a white rag tied around his neck.", "مارلو گروهی از این مردان را دید که در سایه درختی استراحت می‌کردند، چنان لاغر و چنان فرسوده که بیشتر مرده از زنده به نظر می‌رسیدند، و دید که یکی از آن‌ها، پسر جوانی، پارچه سفیدی دور گردنش بسته بود."),
                    StoryParagraph("The white rag, he realized, was a sign of innocence, a symbol of the boy's hope that he was not yet beyond all help, that someone somewhere might still care whether he lived or died.", "پارچه سفید، فهمید، نشانه‌ای از معصومیت بود، نمادی از امید پسر که هنوز از هر کمکی فراتر نرفته، که کسی جایی هنوز ممکن است اهمیت بدهد که زنده می‌ماند یا می‌میرد."),
                    StoryParagraph("But Marlow knew, even as he watched, that this hope was an illusion, that the boy would soon die like all the others, and that his death would be recorded in no book and mourned by no one.", "اما مارلو می‌دانست، حتی همان‌طور که تماشا می‌کرد، که این امید توهمی است، که پسر به‌زودی مثل همه دیگران می‌میرد و مرگش در هیچ کتابی ثبت نمی‌شود و هیچ‌کس برایش عزادار نمی‌شود."),
                    StoryParagraph("Marlow walked through the station and saw more of the same, more suffering, more degradation, more evidence that the Company cared nothing for the lives of the men it employed or enslaved.", "مارلو در ایستگاه قدم زد و بیشتر از همین را دید، درد بیشتر، انحطاط بیشتر، شواهد بیشتر که کمپانی هیچ اهمیتی برای زندگی مردانی که استخدام یا به بردگی می‌گرفت قائل نبود."),
                    StoryParagraph("He met the chief accountant of the station, a man who dressed in immaculate white clothes and who kept his books in perfect order despite the chaos around him, a man who seemed to care more for his ledgers than for the lives of those around him.", "او حسابدار ارشد ایستگاه را ملاقات کرد، مردی که لباس‌های سفید بی‌عیب می‌پوشید و کتاب‌هایش را با وجود آشوب اطرافش بی‌نقص نگه می‌داشت، مردی که به نظر می‌رسید بیشتر از زندگی اطرافیانش برای دفترهایش اهمیت می‌دهد."),
                    StoryParagraph("The accountant told Marlow about Kurtz, the man he was going to find, and spoke of him with a mixture of admiration and fear, describing him as a prodigy, an emissary of pity and science and progress.", "حسابدار برای مارلو از کورتز گفت، مردی که می‌رفت او را پیدا کند، و با ترکیبی از تحسین و ترس از او سخن گفت، او را نابغه‌ای توصیف کرد، فرستاده‌ای از ترحم و علم و پیشرفت."),
                    StoryParagraph("Kurtz, the accountant said, was a man of great talent and great ambition, a man who had come to Africa to bring light to the darkness, but who had perhaps lost his way in the process, a man who was now more a rumor than a reality.", "حسابدار گفت کورتز مردی با استعداد فراوان و جاه‌طلبی فراوان بود، مردی که به آفریقا آمده بود تا نور به تاریکی بیاورد، اما شاید در این راه گم شده بود، مردی که اکنون بیشتر شایعه بود تا واقعیت."),
                    StoryParagraph("Marlow left the station and continued his journey up the river, traveling in a small steamboat that had been provided by the Company, a boat that would become his home for the next several months.", "مارلو ایستگاه را ترک کرد و سفرش در رود را ادامه داد، در یک قایق بخار کوچک که توسط کمپانی فراهم شده بود، قایقی که خانه‌اش برای چند ماه بعدی می‌شد."),
                    StoryParagraph("The journey was long and difficult, the river was treacherous, the jungle pressed in on both sides, and Marlow felt himself being drawn deeper and deeper into a world that had no connection to the world he had left behind.", "سفر طولانی و دشوار بود، رود خائنانه بود، جنگل از هر دو طرف فشار می‌آورد، و مارلو حس کرد که عمیق‌تر و عمیق‌تر به جهانی کشیده می‌شود که هیچ ارتباطی با جهانی که پشت سر گذاشته نداشت."),
                    StoryParagraph("As he traveled, Marlow began to feel the presence of Kurtz, not as a person but as a force, as an idea that had taken hold of the entire region and that seemed to be waiting for him at the end of the river.", "در حین سفر، مارلو شروع کرد به حس کردن حضور کورتز، نه به‌عنوان یک شخص بلکه به‌عنوان نیرویی، به‌عنوان ایده‌ای که تمام منطقه را تسخیر کرده بود و به نظر می‌رسید در انتهای رود منتظر اوست."),
                    StoryParagraph("The jungle, the river, the silence, the darkness, all of it seemed to be speaking to him, telling him something about the nature of existence that he had never understood before.", "جنگل، رود، سکوت، تاریکی، همه به نظر می‌رسیدند با او سخن می‌گویند، چیزی درباره ماهیت هستی به او می‌گویند که هرگز قبلاً نفهمیده بود."),
                    StoryParagraph("And what they told him was this: that civilization is a fragile thing, a thin veneer over an abyss of savagery that lies waiting within every human heart, ready to swallow us whole at any moment.", "و آنچه به او می‌گفتند این بود: تمدن چیزی شکننده است، پوسته‌ای نازک بر پرتگاهی از وحشی‌گری که در قلب هر انسانی منتظر است، آماده است هر لحظه ما را یکجا ببلعد."),
                    StoryParagraph("Marlow arrived at the Central Station, where he would spend several months waiting for the boat he needed to reach Kurtz's station, and there he learned more about the man he was seeking.", "مارلو به ایستگاه مرکزی رسید، جایی که چند ماه منتظر قایقی می‌ماند که به ایستگاه کورتز برسد، و آنجا بیشتر درباره مردی که در جستجویش بود آموخت."),
                    StoryParagraph("He met the manager of the station, a man who had no talent, no intelligence, no imagination, but who had survived in the Congo longer than anyone else, and who seemed to have achieved this survival through an utter lack of anything that might make him a threat.", "او مدیر ایستگاه را ملاقات کرد، مردی بدون استعداد، بدون هوش، بدون تخیل، اما کسی که طولانی‌تر از هر کس دیگری در کنگو زنده مانده بود و به نظر می‌رسید این بقا را از طریق فقدان مطلق هر چیزی که ممکن بود او را تهدید کند به دست آورده بود."),
                    StoryParagraph("The manager told Marlow that Kurtz was ill, that he might not survive, and that it was important to reach him before it was too late, though Marlow suspected that the manager's concern was less for Kurtz than for the ivory that Kurtz had collected.", "مدیر به مارلو گفت کورتز بیمار است، شاید زنده نماند و مهم است قبل از خیلی دیر شدن به او برسند، هرچند مارلو گمان می‌کرد نگرانی مدیر کمتر برای کورتز و بیشتر برای عاجی بود که کورتز جمع کرده بود."),
                    StoryParagraph("Marlow also met a man who called himself a brickmaker, though he made no bricks, and who spent his days scheming and gossiping and trying to advance his position in the Company.", "مارلو همچنین مردی را ملاقات کرد که خود را آجرساز می‌نامید، هرچند آجر نمی‌ساخت، و روزهایش را به نقشه‌کشی و غیبت و تلاش برای پیشبرد مقامش در کمپانی می‌گذراند."),
                    StoryParagraph("The brickmaker told Marlow that Kurtz was a remarkable man, a man of great ideas, a man who had been sent to Africa by the Company's directors with a special mission, though what that mission was, no one seemed to know.", "آجرساز به مارلو گفت کورتز مردی قابل توجه بود، مردی با ایده‌های بزرگ، مردی که توسط مدیران کمپانی با مأموریتی ویژه به آفریقا فرستاده شده بود، هرچند کسی نمی‌دانست آن مأموریت چه بود."),
                    StoryParagraph("The brickmaker also told Marlow that Kurtz had become the subject of a report that he had written, a report that spoke of Kurtz as an emissary of pity and science and progress, a report that had been sent to the Company's headquarters in Brussels.", "آجرساز همچنین به مارلو گفت کورتز موضوع گزارشی شده بود که او نوشته بود، گزارشی که از کورتز به‌عنوان فرستاده‌ای از ترحم و علم و پیشرفت سخن می‌گفت، گزارشی که به مرکز کمپانی در بروکسل فرستاده شده بود."),
                    StoryParagraph("Marlow, who had been asked by the Company to write a report about his journey, found himself caught between the various factions at the station, each of whom wanted him to see things their way.", "مارلو، که از او خواسته شده بود گزارشی درباره سفرش بنویسد، خود را بین جناح‌های مختلف ایستگاه گرفتار یافت، هر یک از آنان می‌خواستند او چیزها را از دید آنان ببیند."),
                    StoryParagraph("But Marlow had no interest in their petty politics, and he had no interest in the Company's profits, and he had no interest in anything except reaching Kurtz and discovering for himself what had happened to the man.", "اما مارلو هیچ علاقه‌ای به سیاست‌های حقیرشان نداشت و هیچ علاقه‌ای به سودهای کمپانی نداشت و هیچ علاقه‌ای به چیزی جز رسیدن به کورتز و کشف کردن خود آنچه برای آن مرد اتفاق افتاده بود نداشت."),
                    StoryParagraph("And so he waited, and he watched, and he listened, and he learned more about the Congo and about human nature than he had ever wanted to know.", "و اینگونه منتظر ماند و تماشا کرد و گوش داد و بیشتر درباره کنگو و طبیعت انسانی آموخت از آنچه هرگز می‌خواست بداند."),
                    StoryParagraph("He learned that the Company cared nothing for the Africans it claimed to be civilizing, that it cared nothing for the men it employed, that it cared only for the ivory that could be extracted from the interior of the continent.", "او آموخت که کمپانی هیچ اهمیتی برای آفریقایی‌هایی که ادعا می‌کرد تمدن‌شان می‌کند قائل نبود، هیچ اهمیتی برای مردانی که استخدام می‌کرد نداشت، تنها به عاجی اهمیت می‌داد که می‌شد از درون قاره استخراج کرد."),
                    StoryParagraph("He learned that the darkness of the Congo was not in the land or in the people, but in the hearts of the Europeans who had come to exploit both, and that this darkness was spreading like a plague.", "او آموخت که تاریکی کنگو نه در سرزمین بود و نه در مردم، بلکه در قلب اروپایی‌هایی بود که برای استثمار هر دو آمده بودند، و این تاریکی مثل طاعون پخش می‌شد."),
                    StoryParagraph("And he learned that Kurtz, whom he had never met, was somehow at the center of it all, a man who had become both a victim and a perpetrator of the very darkness he had come to dispel.", "و آموخت که کورتز، که هرگز ملاقاتش نکرده بود، به نوعی در مرکز همه چیز بود، مردی که هم قربانی و هم مرتکب همان تاریکی شده بود که برای از بین بردنش آمده بود."),
                    StoryParagraph("And so ended the second part of Marlow's tale, with the steamboat finally repaired and the journey up the river about to begin in earnest.", "و اینگونه بخش دوم داستان مارلو به پایان رسید، با قایق بخار که سرانجام تعمیر شده بود و سفری که به‌طور جدی در رود در شرف آغاز بود.")
                )
            ),
            StoryChapter(
                number = 3, title = "The Journey Up the River", titlePersian = "سفر در رود",
                paragraphs = listOf(
                    StoryParagraph("The steamboat finally set off up the river, and Marlow felt a strange mixture of excitement and dread as the shores of the Central Station receded behind him and the vast wilderness of the Congo opened up before him.", "قایق بخار سرانجام در رود به راه افتاد و مارلو ترکیبی عجیب از هیجان و هراس را حس کرد وقتی ساحل ایستگاه مرکزی از پشت سرش دور شد و بیابان وسیع کنگو پیش رویش گشوده شد."),
                    StoryParagraph("The river was unlike anything he had ever seen, a dark and sluggish current that seemed to move with a will of its own, as if it were a living creature that had swallowed the land and was now digesting it.", "رود مثل هیچ چیز دیگری که دیده بود نبود، جریانی تاریک و کند که به نظر می‌رسید با اراده خودش حرکت می‌کند، گویی موجودی زنده بود که زمین را بلعیده و اکنون در حال هضمش بود."),
                    StoryParagraph("On either side of the river the jungle rose like a wall, an impenetrable mass of green that seemed to press in on the boat, and Marlow felt that if the boat stopped for even a moment, the jungle would swallow it whole.", "در هر دو طرف رود، جنگل مثل دیواری برمی‌خاست، توده‌ای نفوذناپذیر از سبزی که به نظر می‌رسید بر قایق فشار می‌آورد، و مارلو حس کرد اگر قایق حتی لحظه‌ای بایستد، جنگل آن را یکجا می‌بلعد."),
                    StoryParagraph("The air was thick with heat and humidity, and with the sounds of insects and birds and animals that Marlow could not identify, a cacophony of life that seemed both beautiful and terrifying in its intensity.", "هوا از گرما و رطوبت و از صداهای حشرات و پرندگان و حیواناتی که مارلو نمی‌توانست شناسایی کند غلیظ بود، همهمه‌ای از زندگی که در شدتش هم زیبا و هم هراس‌آور به نظر می‌رسید."),
                    StoryParagraph("The men on the boat, the pilgrims as Marlow called them, were useless, more concerned with their own comfort and their own advancement than with the mission they were supposed to be on.", "مردان روی قایق، زائرانی که مارلو آن‌ها را می‌نامید، بی‌فایده بودند، بیشتر نگران راحتی و پیشرفت خودشان بودند تا مأموریتی که قرار بود در آن باشند."),
                    StoryParagraph("They were men who had come to Africa for profit, not for adventure, and they were terrified of the wilderness around them, a terror that made them both cruel and cowardly.", "آن‌ها مردانی بودند که برای سود به آفریقا آمده بودند، نه برای ماجراجویی، و از بیابان اطرافشان وحشت داشتند، وحشتی که آنان را هم بی‌رحم و هم بزدل می‌کرد."),
                    StoryParagraph("Marlow, by contrast, felt a strange affinity with the river and the jungle, a feeling that he was returning to something he had always known, that he was remembering something he had never been taught.", "مارلو، در مقابل، هم‌دلی عجیبی با رود و جنگل حس می‌کرد، حسی که به چیزی بازمی‌گشت که همیشه می‌شناخته، که چیزی را به یاد می‌آورد که هرگز یادش نداده بودند."),
                    StoryParagraph("He had learned, long ago, that the sea was his only true home, but here, on this dark river, he felt that he was discovering a home even deeper than the sea, a home that lay at the very origins of human existence.", "او مدت‌ها پیش آموخته بود که دریا تنها خانه واقعی‌اش است، اما اینجا، بر این رود تاریک، حس می‌کرد که خانه‌ای حتی عمیق‌تر از دریا کشف می‌کند، خانه‌ای که در اصل و بنیاد وجود بشری جای داشت."),
                    StoryParagraph("And it was here, in this place that seemed so alien to the European mind, that Marlow began to understand something about the nature of human beings and the nature of civilization itself.", "و اینجا بود، در این مکان که برای ذهن اروپایی چنان بیگانه به نظر می‌رسید، که مارلو شروع کرد به فهم چیزی درباره ماهیت انسان‌ها و ماهیت خود تمدن."),
                    StoryParagraph("The journey was long and slow, and as it progressed, Marlow began to feel the presence of Kurtz more and more, as if the man were not merely at the end of the river but inside his own head, whispering to him, tempting him.", "سفر طولانی و آهسته بود و همان‌طور که پیش می‌رفت، مارلو بیشتر و بیشتر حضور کورتز را حس می‌کرد، گویی آن مرد نه تنها در انتهای رود بود بلکه درون سر خودش، به او زمزمه می‌کرد، وسوسه‌اش می‌کرد."),
                    StoryParagraph("The silence of the jungle was profound, broken only by the churning of the boat's engines and the occasional cries of unseen creatures, and in that silence Marlow heard the voice of his own darkness.", "سکوت جنگل عمیق بود، تنها با صدای موتورهای قایق و گاهی فریادهای موجودات نادیده شکسته می‌شد، و در آن سکوت مارلو صدای تاریکی خودش را شنید."),
                    StoryParagraph("He began to understand, as he had never understood before, that the darkness the Europeans spoke of, the darkness they claimed to be bringing light to, was not in the African wilderness but in their own hearts.", "او شروع کرد به فهمیدن، آنگونه که هرگز قبلاً نفهمیده بود، که تاریکی‌ای که اروپایی‌ها از آن حرف می‌زدند، تاریکی‌ای که ادعا می‌کردند نور به آن می‌آورند، نه در بیابان آفریقا بود بلکه در قلب خودشان."),
                    StoryParagraph("They had come to Africa to civilize the savages, but they were themselves the true savages, men who had lost all sense of human decency and who cared only for the ivory that could be extracted from the land.", "آن‌ها به آفریقا آمده بودند تا وحشی‌ها را متمدن کنند، اما خودشان وحشی‌های واقعی بودند، مردانی که تمام حس نجابت انسانی را از دست داده بودند و تنها به عاجی که می‌شد از این سرزمین استخراج کرد اهمیت می‌دادند."),
                    StoryParagraph("The steamboat moved slowly up the river, fighting against the current, and Marlow watched the shore, looking for any sign of Kurtz's station, any hint of the man he had come so far to find.", "قایق بخار آهسته در رود پیش می‌رفت، در برابر جریان مبارزه می‌کرد، و مارلو ساحل را تماشا می‌کرد، به دنبال هر نشانه‌ای از ایستگاه کورتز، هر اشاره‌ای از مردی که اینقدر دور آمده بود تا پیدا کند."),
                    StoryParagraph("He saw villages on the shore, native villages, where people watched the boat pass with a mixture of curiosity and fear, and he wondered what they thought of these strange white men who had come to their land.", "او دهکده‌هایی در ساحل دید، دهکده‌های بومی، جایی که مردم با ترکیبی از کنجکاوی و ترس تماشا می‌کردند که قایق می‌گذرد، و حیران بود که آنان درباره این مردان سفیدپوست عجیبی که به سرزمینشان آمده بودند چه فکر می‌کنند."),
                    StoryParagraph("He saw the results of the Company's presence: burned villages, dead bodies, the bones of men and animals scattered on the shore, and the stench of death that hung over everything like a fog.", "او نتایج حضور کمپانی را دید: دهکده‌های سوخته، اجساد مرده، استخوان‌های انسان‌ها و حیوانات که در ساحل پراکنده بودند، و بوی گندیده مرگ که مثل مه بر همه چیز آویزان بود."),
                    StoryParagraph("The journey was a nightmare, but Marlow could not wake up from it, and he knew that he would never be able to forget what he had seen and heard on this river, that it would haunt him for the rest of his life.", "سفر کابوسی بود، اما مارلو نمی‌توانست از آن بیدار شود، و می‌دانست هرگز نمی‌تواند آنچه در این رود دیده و شنیده را فراموش کند، که باقی عمرش تعقیبش می‌کند."),
                    StoryParagraph("And then, one day, as the boat rounded a bend in the river, Marlow saw something on the shore that made his heart stop, a sight that he would remember until his dying day.", "و سپس، یک روز، وقتی قایق از پیچی در رود عبور کرد، مارلو چیزی در ساحل دید که قلبش را ایستاند، منظره‌ای که تا روز مرگش به یاد می‌آورد."),
                    StoryParagraph("It was a small hut, abandoned and half ruined, and on the wall of the hut, in faded letters, was a message, a message from Kurtz himself, a message that spoke of the man's mission and of his vision.", "کلبه‌ای کوچک بود، رهاشده و نیمه‌ویران، و روی دیوار کلبه، با حروفی محو، پیامی بود، پیامی از خود کورتز، پیامی که از مأموریت آن مرد و از چشم‌اندازش سخن می‌گفت."),
                    StoryParagraph("The message said: At the end of the river, there is a man who has seen the truth, who has faced the darkness and has not been destroyed by it, who has become one with it.", "پیام می‌گفت: در انتهای رود، مردی است که حقیقت را دیده، با تاریکی روبرو شده و توسط آن نابود نشده، با آن یکی شده."),
                    StoryParagraph("Marlow read the message and felt a chill run down his spine, for he understood in that moment that Kurtz was not merely a man but a symbol, a symbol of everything that could happen to a human being when civilization was stripped away.", "مارلو پیام را خواند و لرزه‌ای در ستون فقراتش حس کرد، زیرا در آن لحظه فهمید کورتز تنها یک مرد نیست بلکه نمادی است، نمادی از هر چیزی که می‌تواند برای یک انسان اتفاق بیفتد وقتی تمدن از او گرفته می‌شود."),
                    StoryParagraph("He understood that Kurtz was both a warning and a temptation, a warning of what he himself might become, and a temptation to follow the same path, to abandon the rules and restraints of civilization and to live according to his own will alone.", "او فهمید کورتز هم هشدار بود و هم وسوسه، هشداری از آنچه خودش ممکن بود بشود، و وسوسه‌ای برای دنبال کردن همان مسیر، برای رها کردن قواعد و قیدهای تمدن و زندگی کردن تنها بر اساس اراده خویش."),
                    StoryParagraph("The boat continued up the river, and Marlow felt that he was approaching not merely a place but a state of being, a state in which the boundaries between self and other, between good and evil, between civilization and savagery, had all dissolved.", "قایق در رود پیش می‌رفت و مارلو حس کرد که نه تنها به مکانی بلکه به حالتی از وجود نزدیک می‌شود، حالتی که در آن مرزهای میان خود و دیگری، میان خوب و بد، میان تمدن و وحشی‌گری، همه حل شده بودند."),
                    StoryParagraph("And then, at last, the boat arrived at Kurtz's station, and Marlow stepped onto the shore of a place that seemed to be at the very edge of the world, a place where the darkness was so complete that even the sun seemed unable to penetrate it.", "و سپس، سرانجام، قایق به ایستگاه کورتز رسید و مارلو بر ساحل جایی قدم گذاشت که به نظر می‌رسید در همان لبه جهان باشد، جایی که تاریکی چنان کامل بود که حتی خورشید هم به نظر می‌رسید قادر به نفوذ در آن نیست."),
                    StoryParagraph("He saw the station, a collection of huts and buildings, and he saw the natives who lived there, men who moved with a strange grace and who seemed to be waiting for something, for someone.", "او ایستگاه را دید، مجموعه‌ای از کلبه‌ها و ساختمان‌ها، و بومیانی را دید که آنجا زندگی می‌کردند، مردانی که با ظرافتی عجیب حرکت می‌کردند و به نظر می‌رسید منتظر چیزی هستند، کسی."),
                    StoryParagraph("And then he saw Kurtz, or what was left of Kurtz, a man so thin and so pale that he seemed more ghost than human, a man whose eyes burned with a fire that was both terrible and beautiful.", "و سپس کورتز را دید، یا آنچه از کورتز باقی مانده بود، مردی چنان لاغر و چنان رنگ‌پریده که بیشتر شبح از انسان به نظر می‌رسید، مردی که چشمانش با آتشی می‌سوخت که هم هولناک و هم زیبا بود."),
                    StoryParagraph("Kurtz spoke, and his voice was weak but his words were strong, words about truth and about darkness, words about the horror of existence and the necessity of facing it, words that Marlow would never forget.", "کورتز سخن گفت و صدایش ضعیف بود اما کلماتش قوی، کلماتی درباره حقیقت و درباره تاریکی، کلماتی درباره وحشت وجود و ضرورت رویارویی با آن، کلماتی که مارلو هرگز فراموش نمی‌کرد."),
                    StoryParagraph("And so ended the third part of Marlow's tale, with the meeting that he had traveled so far to achieve, a meeting that would change him forever.", "و اینگونه بخش سوم داستان مارلو به پایان رسید، با دیداری که اینقدر دور سفر کرده بود تا به آن برسد، دیداری که او را برای همیشه تغییر می‌داد.")
                )
            ),
            StoryChapter(
                number = 4, title = "Kurtz", titlePersian = "کورتز",
                paragraphs = listOf(
                    StoryParagraph("Marlow spent several days at Kurtz's station, and during those days he came to know the man, or rather he came to know what the man had become, for the Kurtz he met was not the Kurtz who had come to Africa years before.", "مارلو چند روز در ایستگاه کورتز ماند و در آن روزها با آن مرد آشنا شد، یا بهتر، با آنچه آن مرد شده بود آشنا شد، زیرا کورتزی که ملاقات کرد همان کورتزی نبود که سال‌ها پیش به آفریقا آمده بود."),
                    StoryParagraph("The Kurtz he met was a man who had gone beyond all the boundaries that civilization imposes on human beings, a man who had abandoned all the rules and restraints that keep us from becoming monsters, a man who had become something both more and less than human.", "کورتزی که ملاقات کرد مردی بود که از تمام مرزهایی که تمدن بر انسان‌ها تحمیل می‌کند فراتر رفته بود، مردی که تمام قواعد و قیدهایی که ما را از تبدیل شدن به هیولا بازمی‌دارد رها کرده بود، مردی که به چیزی هم بیشتر و هم کمتر از انسان تبدیل شده بود."),
                    StoryParagraph("Kurtz was a man of great intelligence and great eloquence, a man who could speak about anything with a passion and a conviction that made others believe him, but he was also a man who had lost all moral compass.", "کورتز مردی با هوش فراوان و فصاحت فراوان بود، مردی که می‌توانست درباره هر چیزی با شوری و اعتقادی سخن بگوید که دیگران را وادار به باور او می‌کرد، اما همچنین مردی بود که تمام قطب‌نمای اخلاقی را از دست داده بود."),
                    StoryParagraph("He had come to Africa with a mission, a mission to bring light to the darkness, but somewhere along the way, the darkness had entered him, had become a part of him, and he had become its servant rather than its master.", "او با مأموریتی به آفریقا آمده بود، مأموریتی برای آوردن نور به تاریکی، اما جایی در طول راه، تاریکی واردش شده بود، بخشی از او شده بود، و او خدمتگزارش شده بود نه اربابش."),
                    StoryParagraph("Kurtz had collected more ivory than any other agent, but he had also collected something else, something more terrible: the worship of a tribe that had come to see him as a god, and the heads of rebels that he had placed on stakes around his hut.", "کورتز بیشتر از هر مأمور دیگری عاج جمع کرده بود، اما چیز دیگری هم جمع کرده بود، چیزی هولناک‌تر: پرستش قبیله‌ای که او را همچون خدا می‌دیدند، و سرهای شورشیانی که بر نیزه‌های اطراف کلبه‌اش گذاشته بود."),
                    StoryParagraph("He had become the master of the tribe, and the tribe had become his instrument, an instrument that he used to collect ivory and to enforce his will on all who opposed him.", "او ارباب قبیله شده بود و قبیله ابزارش شده بود، ابزاری که برای جمع کردن عاج و تحمیل اراده‌اش بر همه مخالفانش استفاده می‌کرد."),
                    StoryParagraph("The natives worshipped him, and Marlow could see why, for Kurtz had become something more than human in their eyes, a being who had transcended the ordinary limits of existence and who now lived in a realm of his own creation.", "بومیان او را می‌پرستیدند و مارلو می‌توانست دلیلش را ببیند، زیرا کورتز در چشمان آنان به چیزی بیشتر از انسان تبدیل شده بود، موجودی که از مرزهای معمول وجود فراتر رفته بود و اکنون در قلمروی از آفرینش خویش زندگی می‌کرد."),
                    StoryParagraph("Marlow watched Kurtz and saw in him both the worst and the best of humanity, both the potential for greatness and the potential for horror, and he understood that these two potentials were not opposites but two sides of the same coin.", "مارلو کورتز را تماشا کرد و در او هم بدترین و هم بهترین بشریت را دید، هم توانایی بزرگی و هم توانایی وحشت، و فهمید این دو توانایی متضاد نیستند بلکه دو روی یک سکه‌اند."),
                    StoryParagraph("Kurtz spoke to Marlow about many things, about the nature of civilization, about the darkness that lies at the heart of all human beings, about the importance of facing that darkness rather than fleeing from it.", "کورتز برای مارلو از بسیاری چیزها گفت، درباره ماهیت تمدن، درباره تاریکی‌ای که در قلب تمام انسان‌ها جای دارد، درباره اهمیت رویارویی با آن تاریکی به جای فرار از آن."),
                    StoryParagraph("He spoke about the horror, a phrase that he repeated again and again, and Marlow came to understand that the horror was not something external, not something that existed in the African wilderness, but something internal, something that exists in every human heart.", "او از وحشت سخن گفت، عبارتی که بارها و بارها تکرار کرد، و مارلو شروع کرد به فهمیدن که وحشت چیزی بیرونی نبود، نه چیزی که در بیابان آفریقا وجود داشت، بلکه چیزی درونی، چیزی که در قلب هر انسانی وجود دارد."),
                    StoryParagraph("Kurtz gave Marlow a packet of papers, a report that he had written for the Company, a report about the suppression of savage customs, and he asked Marlow to keep it safe.", "کورتز بسته‌ای کاغذ به مارلو داد، گزارشی که برای کمپانی نوشته بود، گزارشی درباره سرکوب آداب وحشیانه، و از مارلو خواست آن را امن نگه دارد."),
                    StoryParagraph("Marlow read the report later and found it to be a beautiful piece of writing, eloquent and moving, a report that called on the Company to treat the natives as human beings rather than as tools, and it ended with a strange postscript.", "مارلو بعداً گزارش را خواند و آن را نوشته‌ای زیبا یافت، فصیح و تأثیرگذار، گزارشی که از کمپانی می‌خواست با بومیان همچون انسان رفتار کند نه ابزار، و با ضمیمه‌ای عجیب پایان می‌یافت."),
                    StoryParagraph("The postscript said simply: Exterminate all the brutes, and Marlow understood in that moment that Kurtz had seen the truth, had seen what civilization really was, a thin veneer over the savagery that lies at the heart of all human beings.", "ضمیمه به‌سادگی می‌گفت: همه وحشی‌ها را نابود کنید، و مارلو در آن لحظه فهمید کورتز حقیقت را دیده بود، دیده بود تمدن واقعاً چیست، پوسته‌ای نازک بر وحشی‌گری که در قلب تمام انسان‌ها جای دارد."),
                    StoryParagraph("Kurtz was ill, terribly ill, and it was clear that he would not survive much longer, but he refused to leave his station, refused to abandon the tribe that worshipped him, refused to return to the civilization that had made him what he was.", "کورتز بیمار بود، بسیار بیمار، و واضح بود که زیاد زنده نمی‌ماند، اما از ترک ایستگاهش امتناع کرد، از رها کردن قبیله‌ای که او را می‌پرستیدند امتناع کرد، از بازگشت به تمدنی که او را آنچه بود ساخته بود امتناع کرد."),
                    StoryParagraph("But Marlow had been sent to bring him back, and he was determined to do so, even if it meant defying Kurtz's own wishes, even if it meant dragging the man onto the boat by force.", "اما مارلو فرستاده شده بود تا او را بازگرداند و مصمم بود این کار را بکند، حتی اگر به معنای مخالفت با خواسته‌های خود کورتز بود، حتی اگر به معنای کشاندن آن مرد به قایق با زور بود."),
                    StoryParagraph("And so one night, when Kurtz had crept away from the station and was crawling toward the fires of the tribe, Marlow went after him, found him, and brought him back.", "و اینگونه یک شب، وقتی کورتز از ایستگاه دزدیده بود و به سمت آتش‌های قبیله می‌خزید، مارلو دنبالش رفت، پیدایش کرد و بازگرداندش."),
                    StoryParagraph("Kurtz did not resist, or rather he resisted only weakly, and as Marlow carried him back to the boat, the man spoke, spoke of the darkness, spoke of the horror, spoke of things that Marlow would never be able to forget.", "کورتز مقاومت نکرد، یا بهتر، فقط ضعیف مقاومت کرد، و همان‌طور که مارلو او را به قایق برمی‌گرداند، آن مرد سخن گفت، از تاریکی گفت، از وحشت گفت، از چیزهایی گفت که مارلو هرگز قادر به فراموش کردنشان نمی‌شد."),
                    StoryParagraph("Marlow put Kurtz in a cabin on the boat and ordered the crew to prepare to depart, and as the boat pulled away from the station, Marlow looked back and saw the natives lined up on the shore, watching their god leave them.", "مارلو کورتز را در کابینی روی قایق گذاشت و به خدمه دستور داد آماده حرکت شوند، و همان‌طور که قایق از ایستگاه دور می‌شد، مارلو به عقب نگاه کرد و بومیان را دید که در ساحل صف کشیده بودند و می‌دیدند خدایشان آنان را ترک می‌کند."),
                    StoryParagraph("It was a sight that Marlow would never forget, a sight that spoke of the power of belief and the power of illusion, a sight that showed how easily human beings could be made to worship something that was not worthy of worship.", "منظره‌ای بود که مارلو هرگز فراموش نمی‌کرد، منظره‌ای که از قدرت باور و قدرت توهم سخن می‌گفت، منظره‌ای که نشان می‌داد چقدر راحت می‌توان انسان‌ها را وادار به پرستش چیزی کرد که لایق پرستش نیست."),
                    StoryParagraph("The journey down the river was long and difficult, and Kurtz grew weaker and weaker with each passing day, until finally, on a night when the boat was anchored near a small island, he died.", "سفر در رود طولانی و دشوار بود و کورتز هر روز ضعیف‌تر می‌شد، تا اینکه سرانجام، شبی که قایق نزدیک جزیره کوچکی لنگر انداخته بود، مرد."),
                    StoryParagraph("His last words were: The horror, the horror, and Marlow, who was with him at the end, understood that these words meant more than he could ever say, that they were a summary of everything Kurtz had seen and learned.", "آخرین کلماتش این بود: وحشت، وحشت، و مارلو، که در پایان با او بود، فهمید این کلمات بیش از آنچه می‌توانست بگوید معنا داشتند، که خلاصه‌ای از هر چیزی بودند که کورتز دیده و آموخته بود."),
                    StoryParagraph("The horror was not the African wilderness, not the savagery of the natives, not the cruelty of the Company, but the darkness that lies at the heart of all human beings, the darkness that we spend our lives trying to hide from ourselves.", "وحشت نه بیابان آفریقا بود، نه وحشی‌گری بومیان، نه بی‌رحمی کمپانی، بلکه تاریکی‌ای بود که در قلب تمام انسان‌ها جای دارد، تاریکی‌ای که عمرمان را صرف پنهان کردنش از خودمان می‌کنیم."),
                    StoryParagraph("Kurtz had faced that darkness, had become one with it, and had died with the knowledge of what he truly was, and that knowledge, that final honesty, was perhaps the only redemption possible in a world without God.", "کورتز با آن تاریکی روبرو شده بود، با آن یکی شده بود، و با دانش آنچه واقعاً بود مرده بود، و آن دانش، آن صداقت نهایی، شاید تنها رستگاری ممکن در جهانی بدون خدا بود."),
                    StoryParagraph("Marlow buried Kurtz on the shore of the river, and then continued his journey back to civilization, a journey that would take him to Brussels, to the woman who had loved Kurtz, and to a final lie that would haunt him forever.", "مارلو کورتز را در ساحل رود دفن کرد و سپس سفرش را به تمدن ادامه داد، سفری که او را به بروکسل می‌برد، به زنی که کورتز را دوست داشت، و به دروغ نهایی که او را برای همیشه تعقیب می‌کرد."),
                    StoryParagraph("And so ended the fourth part of Marlow's tale, with the death of the man he had come so far to find, a death that was also a kind of revelation.", "و اینگونه بخش چهارم داستان مارلو با مرگ مردی به پایان رسید که اینقدر دور آمده بود تا پیدایش کند، مرگی که نوعی مکاشفه هم بود.")
                )
            ),
            StoryChapter(
                number = 5, title = "The Return", titlePersian = "بازگشت",
                paragraphs = listOf(
                    StoryParagraph("Marlow returned to Europe a changed man, though he could not explain to anyone, not even to himself, exactly what had changed, for the change was not in his circumstances but in his soul.", "مارلو به اروپا مردی تغییر یافته بازگشت، هرچند نمی‌توانست به کسی توضیح دهد، حتی به خودش، دقیقاً چه چیزی تغییر کرده بود، زیرا تغییر در شرایطش نبود بلکه در روحش بود."),
                    StoryParagraph("He had gone to Africa as an Englishman, as a product of Western civilization, with all the assumptions and beliefs that such a background entailed, and he had returned with those assumptions shattered, those beliefs shaken to their foundations.", "او به‌عنوان یک انگلیسی به آفریقا رفته بود، به‌عنوان محصولی از تمدن غربی، با تمام فرض‌ها و باورهایی که چنین پیشینه‌ای به همراه داشت، و با آن فرض‌های شکسته و آن باورهای متزلزل تا بنیادشان بازگشته بود."),
                    StoryParagraph("He found that he could no longer take pleasure in the things he had once enjoyed, that the comfortable life of Europe seemed hollow and meaningless, that the people around him seemed to be sleepwalking through their lives.", "او دریافت که دیگر نمی‌تواند از چیزهایی که روزی لذت می‌برد لذت ببرد، که زندگی راحت اروپا توخالی و بی‌معنا به نظر می‌رسید، که مردم اطرافش به نظر می‌رسیدند در خواب راه می‌روند در زندگیشان."),
                    StoryParagraph("He found that he could not speak of what he had seen and learned, that the words would not come, that even when he tried to explain, his listeners would not understand, would think him mad, would dismiss what he said as exaggeration.", "او دریافت که نمی‌تواند از آنچه دیده و آموخته سخن بگوید، که کلمات نمی‌آمدند، که حتی وقتی تلاش می‌کرد توضیح دهد، شنوندگانش نمی‌فهمیدند، او را دیوانه می‌پنداشتند، آنچه می‌گفت را اغراق می‌دانستند."),
                    StoryParagraph("He found that the truth he had learned in Africa, the truth about the darkness at the heart of human beings, was a truth that no one in Europe wanted to hear, a truth that everyone in Europe was trying to forget.", "او دریافت که حقیقتی که در آفریقا آموخته بود، حقیقت درباره تاریکی در قلب انسان‌ها، حقیقتی بود که هیچ‌کس در اروپا نمی‌خواست بشنود، حقیقتی که همه در اروپا تلاش می‌کردند فراموشش کنند."),
                    StoryParagraph("Marlow had brought back Kurtz's papers, and among them was a packet of letters that Kurtz had written to a woman in Brussels, a woman who had been engaged to him, a woman who still believed in him.", "مارلو کاغذهای کورتز را بازگردانده بود و در میان آن‌ها بسته‌ای از نامه‌ها بود که کورتز به زنی در بروکسل نوشته بود، زنی که نامزدش بوده، زنی که هنوز به او باور داشت."),
                    StoryParagraph("Marlow visited this woman, whose name he never revealed, in her apartment in Brussels, an apartment that was full of memories of Kurtz, photographs and letters and mementos of a man she had loved and lost.", "مارلو این زن را، که نامش را هرگز فاش نکرد، در آپارتمانش در بروکسل ملاقات کرد، آپارتمانی پر از خاطرات کورتز، عکس‌ها و نامه‌ها و یادگاری‌هایی از مردی که دوست داشته و از دست داده بود."),
                    StoryParagraph("She was a woman of great beauty and great sorrow, a woman who had loved Kurtz with all her heart and who could not accept that he was gone, who could not accept that the man she had loved had become something else entirely.", "زنی بود با زیبایی فراوان و اندوه فراوان، زنی که کورتز را با تمام قلبش دوست داشته و نمی‌توانست بپذیرد که رفته، نمی‌توانست بپذیرد که مردی که دوست داشته به چیزی کاملاً متفاوت تبدیل شده بود."),
                    StoryParagraph("She spoke to Marlow about Kurtz with passion and with grief, told him of the man's genius, of his eloquence, of his noble ideals, of his vision of a world in which all people would be free and equal and enlightened.", "او با شور و اندوه درباره کورتز با مارلو سخن گفت، از نابغه بودن آن مرد، از فصاحتش، از آرمان‌های نجیبش، از چشم‌اندازش از جهانی که در آن همه مردم آزاد و برابر و روشن‌فکر باشند."),
                    StoryParagraph("Marlow listened in silence, knowing that the Kurtz she described was not the Kurtz he had met, that the man she had loved was a man who had never existed, a man who had been created by her own hopes and dreams.", "مارلو در سکوت گوش داد، می‌دانست کورتزی که او توصیف می‌کرد همان کورتزی نبود که او ملاقات کرده بود، مردی که او دوست داشته مردی بود که هرگز وجود نداشته، مردی که توسط امیدها و رؤیاهای خودش ساخته شده بود."),
                    StoryParagraph("And then she asked him the question he had been dreading, the question that he had known she would ask, the question that he had no idea how to answer.", "و سپس او پرسشی را از او پرسید که از آن می‌ترسید، پرسشی که می‌دانست می‌پرسد، پرسشی که نمی‌دانست چطور پاسخ دهد."),
                    StoryParagraph("She asked him what Kurtz's last words had been, and Marlow knew that he could not tell her the truth, that the truth would destroy her, that the truth would be an act of cruelty that he could not bring himself to commit.", "او پرسید آخرین کلمات کورتز چه بوده و مارلو می‌دانست که نمی‌تواند حقیقت را به او بگوید، که حقیقت نابودش می‌کند، که حقیقت عملی از بی‌رحمی می‌بود که نمی‌توانست مرتکبش شود."),
                    StoryParagraph("He could not tell her that Kurtz had died with the words 'The horror, the horror' on his lips, that he had died seeing not the beauty of the ideals she believed in but the darkness of what he had become.", "نمی‌توانست به او بگوید کورتز با کلمات «وحشت، وحشت» بر لب مرده بود، که با دیدن نه زیبایی آرمان‌هایی که او باور داشت بلکه تاریکی آنچه شده بود مرده بود."),
                    StoryParagraph("So Marlow lied, he told her that Kurtz's last words had been her name, that he had died thinking of her, that he had loved her until the very end.", "پس مارلو دروغ گفت، به او گفت آخرین کلمات کورتز نام او بوده، که با فکر کردن به او مرده، که تا آخرین لحظه دوستش داشته."),
                    StoryParagraph("It was a small lie, a lie of mercy, but it was a lie nonetheless, and Marlow knew that it was a lie that would haunt him forever, a lie that was a kind of betrayal, a lie that was a kind of self-deception.", "دروغ کوچکی بود، دروغی از رحم، اما دروغ بود با این حال، و مارلو می‌دانست دروغی است که او را برای همیشه تعقیب می‌کند، دروغی که نوعی خیانت بود، دروغی که نوعی خودفریبی بود."),
                    StoryParagraph("For in lying to her, Marlow was also lying to himself, was denying the truth that Kurtz had discovered, was refusing to acknowledge the darkness that he too carried within his own heart.", "زیرا با دروغ گفتن به او، مارلو به خودش هم دروغ می‌گفت، حقیقتی که کورتز کشف کرده بود را انکار می‌کرد، از اعتراف به تاریکی‌ای که خودش هم در قلبش حمل می‌کرد امتناع می‌کرد."),
                    StoryParagraph("And yet, Marlow knew that the lie was also a kind of truth, that the woman needed to believe in the Kurtz she had loved, that she needed to believe in a world where such a love was possible, that she needed to believe that goodness could exist.", "و با این حال، مارلو می‌دانست دروغ نوعی حقیقت هم بود، آن زن نیاز داشت به کورتزی که دوست داشته باور کند، نیاز داشت به جهانی باور کند که در آن چنین عشقی ممکن است، نیاز داشت باور کند که خوبی می‌تواند وجود داشته باشد."),
                    StoryParagraph("Marlow left her apartment and walked through the streets of Brussels, feeling the weight of his lie, feeling the weight of everything he had seen and learned, feeling the weight of a truth that could not be spoken.", "مارلو آپارتمان او را ترک کرد و در خیابان‌های بروکسل قدم زد، سنگینی دروغش را حس می‌کرد، سنگینی هر چیزی که دیده و آموخته بود را حس می‌کرد، سنگینی حقیقتی را که نمی‌شد گفت."),
                    StoryParagraph("He thought about Kurtz, about the man's greatness and the man's horror, about the way that the two were inseparable, about the way that every human being carried within them both the potential for greatness and the potential for horror.", "او به کورتز فکر کرد، به بزرگی آن مرد و وحشت آن مرد، به شیوه‌ای که آن دو جدانشدنی بودند، به شیوه‌ای که هر انسانی در خود هم توانایی بزرگی و هم توانایی وحشت را حمل می‌کند."),
                    StoryParagraph("He thought about the darkness, the darkness that he had seen in Africa, the darkness that he had seen in Kurtz, the darkness that he now recognized in himself, the darkness that was the truth of the human condition.", "او به تاریکی فکر کرد، تاریکی‌ای که در آفریقا دیده بود، تاریکی‌ای که در کورتز دیده بود، تاریکی‌ای که اکنون در خودش می‌شناخت، تاریکی‌ای که حقیقت وضعیت بشری بود."),
                    StoryParagraph("He thought about civilization, about the thin veneer that covers the abyss, about the way that we tell ourselves stories about our own goodness, stories that are lies, but lies that we need in order to live.", "او به تمدن فکر کرد، به پوسته نازکی که پرتگاه را می‌پوشاند، به شیوه‌ای که به خودمان داستان‌هایی درباره خوبی خودمان می‌گوییم، داستان‌هایی که دروغ‌اند، اما دروغ‌هایی که برای زندگی به آن‌ها نیاز داریم."),
                    StoryParagraph("He thought about the lie he had told the woman, and he understood that it was not merely a lie of mercy, but also a lie of necessity, a lie that was necessary because the truth was unbearable.", "او به دروغی فکر کرد که به آن زن گفته بود و فهمید که نه تنها دروغی از رحم بود، بلکه دروغی از ضرورت هم بود، دروغی که ضروری بود زیرا حقیقت غیرقابل تحمل بود."),
                    StoryParagraph("And so Marlow returned to London, to the comfortable life of Europe, carrying within him a truth that could not be spoken, a darkness that could not be shown, a knowledge that could not be shared.", "و اینگونه مارلو به لندن بازگشت، به زندگی راحت اروپا، در درونش حقیقتی حمل می‌کرد که نمی‌شد گفت، تاریکی‌ای که نمی‌شد نشان داد، دانشی که نمی‌شد به اشتراک گذاشت."),
                    StoryParagraph("He continued to tell his story, as he was telling it now on the Nellie, but he told it in such a way that the meaning was not in the words but outside them, enveloping them like a halo, visible only to those who had eyes to see.", "او به تعریف داستانش ادامه داد، همان‌طور که اکنون بر نلی تعریف می‌کرد، اما آن را به شیوه‌ای تعریف می‌کرد که معنا نه در کلمات بود بلکه بیرونشان، احاطه‌کننده‌شان مثل هاله، تنها برای کسانی که چشمی برای دیدن داشتند مرئی."),
                    StoryParagraph("And so ended the fifth part of Marlow's tale, with the return to civilization and the lie that was also a truth, a lie that was also a revelation.", "و اینگونه بخش پنجم داستان مارلو با بازگشت به تمدن و دروغی که حقیقت هم بود به پایان رسید، دروغی که مکاشفه هم بود.")
                )
            ),
            StoryChapter(
                number = 6, title = "The Meaning", titlePersian = "معنا",
                paragraphs = listOf(
                    StoryParagraph("Marlow finished his tale as the tide on the Thames had turned and the sky had grown dark, and for a long moment the men on the Nellie sat in silence, absorbing what they had heard.", "مارلو داستانش را تمام کرد، همان‌طور که جزر و مد در تیمز برگشته بود و آسمان تاریک شده بود، و برای لحظه‌ای طولانی، مردان روی نلی در سکوت نشستند و آنچه شنیده بودند را جذب می‌کردند."),
                    StoryParagraph("They had heard many sea stories in their lives, but this one was different, this one was not about adventure or heroism but about something darker and more difficult, something that none of them could quite name.", "آن‌ها در زندگی‌شان داستان‌های دریایی بسیاری شنیده بودند، اما این یکی متفاوت بود، این یکی درباره ماجراجویی یا قهرمانی نبود بلکه درباره چیزی تاریک‌تر و دشوارتر بود، چیزی که هیچ‌کدام نمی‌توانستند کاملاً نامش را ببرند."),
                    StoryParagraph("The Director of Companies, who was also the captain and the host of the Nellie, broke the silence with a remark about the tide, but no one paid attention, for they were all still somewhere else, somewhere on the Congo, somewhere in the heart of darkness.", "مدیر شرکت‌ها، که ناخدا و میزبان نلی هم بود، سکوت را با اظهارنظری درباره جزر و مد شکست، اما هیچ‌کس توجه نکرد، چون همه‌شان هنوز جایی دیگر بودند، جایی در کنگو، جایی در قلب تاریکی."),
                    StoryParagraph("Marlow himself sat cross-legged on the deck, far away from the others, silent and remote, a man who had become a voice, who had become a storyteller, who had become a witness to something that could not be witnessed without being changed.", "خود مارلو چهارزانو بر عرشه نشست، دور از دیگران، ساکت و منزوی، مردی که به صدایی تبدیل شده بود، به داستان‌گویی، به شاهدی بر چیزی که نمی‌شد شاهدش بود بدون تغییر کردن."),
                    StoryParagraph("He had told his story many times, to many different people, but the story was never the same, for each time he told it, he discovered something new in it, some new layer of meaning that he had not noticed before.", "او داستانش را بارها تعریف کرده بود، برای افراد مختلف، اما داستان هرگز همان نبود، زیرا هر بار که تعریفش می‌کرد، چیز جدیدی در آن کشف می‌کرد، لایه‌ای جدید از معنا که قبلاً متوجهش نشده بود."),
                    StoryParagraph("And this time, telling it to these men on the Nellie, he had discovered something new again, something about the nature of storytelling itself, about the way that a story can contain a truth that the teller himself does not fully understand.", "و این بار، تعریفش برای این مردان روی نلی، دوباره چیز جدیدی کشف کرده بود، چیزی درباره ماهیت خود داستان‌گویی، درباره شیوه‌ای که یک داستان می‌تواند حقیقتی در خود داشته باشد که خود گوینده کاملاً نمی‌فهمد."),
                    StoryParagraph("For the story was not really about Kurtz, nor about Africa, nor about the Company, but about Marlow himself, about what he had learned about his own nature, about the darkness that he had discovered in his own heart.", "زیرا داستان واقعاً درباره کورتز نبود، نه درباره آفریقا، نه درباره کمپانی، بلکه درباره خود مارلو بود، درباره آنچه درباره طبیعت خودش آموخته بود، درباره تاریکی‌ای که در قلب خودش کشف کرده بود."),
                    StoryParagraph("He had gone to Africa as a young man, confident in his beliefs, secure in his identity, sure of what was right and what was wrong, and he had returned with all of that shattered, with nothing but questions.", "او به‌عنوان مرد جوانی به آفریقا رفته بود، مطمئن در باورهایش، ایمن در هویتش، مطمئن از آنچه درست است و آنچه غلط، و با همه آن‌ها شکسته بازگشته بود، با هیچ جز پرسش‌ها."),
                    StoryParagraph("He had seen what human beings are capable of, the heights of nobility and the depths of horror, and he had understood that both are potential in every one of us, waiting for the circumstances that will bring them out.", "او دیده بود انسان‌ها قادر به چه چیزی هستند، اوج‌های نجابت و اعماق وحشت، و فهمیده بود که هر دو در هر یک از ما توانایی‌اند، منتظر شرایطی که آن‌ها را بیرون می‌کشد."),
                    StoryParagraph("And this understanding, more than anything else, had made him a stranger to his own civilization, a man who could no longer take comfort in the comfortable lies that others told themselves.", "و این فهم، بیش از هر چیز دیگری، او را در تمدن خودش غریبه کرده بود، مردی که دیگر نمی‌توانست در دروغ‌های راحت که دیگران به خودشان می‌گفتند تسلی بیابد."),
                    StoryParagraph("He had told the lie to Kurtz's Intended, but he had also told a deeper truth, the truth that love demands illusion, that we cannot love human beings as they really are, that we can only love them as we imagine them to be.", "او به نامزد کورتز دروغ گفته بود، اما حقیقت عمیق‌تری هم گفته بود، حقیقتی که عشق توهم می‌خواهد، که نمی‌توانیم انسان‌ها را آن‌گونه که واقعاً هستند دوست بداریم، که می‌توانیم فقط آن‌گونه که تصور می‌کنیم دوستشان بداریم."),
                    StoryParagraph("And so the story had no clear moral, no simple lesson, no easy answer, for the story itself was a lie that was also a truth, a fiction that was also a confession, a tale that was also a warning.", "و بنابراین داستان درس اخلاقی روشنی نداشت، درس ساده‌ای نداشت، پاسخ آسانی نداشت، زیرا خود داستان دروغی بود که حقیقت هم بود، داستانی که اعتراف هم بود، حکایتی که هشدار هم بود."),
                    StoryParagraph("Marlow had come to understand that the darkness is not in Africa, not in the savages, not in the Company, but in the human heart, in every human heart, in his own heart, and that this darkness is the true subject of all his stories.", "مارلو شروع کرده بود به فهمیدن اینکه تاریکی در آفریقا نیست، در وحشی‌ها نیست، در کمپانی نیست، بلکه در قلب انسانی است، در هر قلب انسانی، در قلب خودش، و این تاریکی موضوع واقعی همه داستان‌های اوست."),
                    StoryParagraph("And what was true of him was true of all of them, of every human being who had ever lived, of every human being who would ever live, for the darkness is the universal inheritance of our species, the price we pay for being conscious.", "و آنچه درباره او صادق بود درباره همه‌شان هم صادق بود، درباره هر انسانی که تا به حال زیسته، درباره هر انسانی که هرگز خواهد زیست، زیرا تاریکی میراث جهانی گونه ماست، بهایی که برای آگاه بودن می‌پردازیم."),
                    StoryParagraph("The men on the Nellie did not fully understand what Marlow had told them, and perhaps they never would, for the truth he had spoken was not a truth that could be grasped by the intellect alone, but only by the whole being.", "مردان روی نلی کاملاً نفهمیدند مارلو چه گفته بود و شاید هرگز نمی‌فهمیدند، زیرا حقیقتی که گفته بود حقیقتی نبود که تنها با عقل درک شود، بلکه تنها با کل وجود."),
                    StoryParagraph("And yet, something in them had been touched, something had been awakened, and they would carry with them forever the memory of this night on the Thames, and the story of a man named Kurtz.", "و با این حال، چیزی در آنان لمس شده بود، چیزی بیدار شده بود، و برای همیشه با خود خاطره این شب روی تیمز را حمل می‌کردند، و داستان مردی به نام کورتز."),
                    StoryParagraph("For stories are not merely entertainment, not merely ways to pass the time, but ways of knowing, ways of understanding, ways of confronting the truths that we cannot face directly.", "زیرا داستان‌ها تنها سرگرمی نیستند، تنها راه‌هایی برای گذراندن وقت نیستند، بلکه راه‌هایی برای دانستن، برای فهمیدن، برای رویارویی با حقیقت‌هایی هستند که نمی‌توانیم مستقیم با آن‌ها روبرو شویم."),
                    StoryParagraph("Marlow had told his story, and in telling it he had given the men a gift, the gift of a truth that could not be given in any other way, the gift of a darkness that could not be seen except through the story that contained it.", "مارلو داستانش را تعریف کرده بود و در تعریفش به آن مردان هدیه‌ای داده بود، هدیه حقیقتی که به هیچ شکل دیگری نمی‌شد داد، هدیه تاریکی‌ای که جز از طریق داستانی که آن را در خود داشت نمی‌شد دید."),
                    StoryParagraph("And so the story ended, as all stories must end, not with a conclusion but with a silence, a silence that was itself a kind of meaning, a silence that was itself a kind of answer.", "و اینگونه داستان تمام شد، همان‌طور که همه داستان‌ها باید تمام شوند، نه با نتیجه‌گیری بلکه با سکوتی، سکوتی که خود نوعی معنا بود، سکوتی که خود نوعی پاسخ بود."),
                    StoryParagraph("The Nellie swung to her anchor on the Thames, the tide was at rest, the wind was nearly calm, and the sky was dark, and somewhere in the heart of the Congo, a man named Kurtz had died with the words 'The horror, the horror' on his lips.", "نلی بر لنگرش در تیمز تاب می‌خورد، جزر و مد آرام بود، باد تقریباً ساکن و آسمان تاریک، و جایی در قلب کنگو، مردی به نام کورتز با کلمات «وحشت، وحشت» بر لب مرده بود."),
                    StoryParagraph("And Marlow sat in silence, having told his tale, having shared his truth, having given his gift, and he knew that he would tell this story again, to others, in other places, for the story had become a part of him, the deepest part, the part that mattered most.", "و مارلو در سکوت نشست، داستانش را گفته بود، حقیقتش را به اشتراک گذاشته بود، هدیه‌اش را داده بود، و می‌دانست این داستان را دوباره تعریف می‌کند، برای دیگران، در جاهای دیگر، زیرا داستان بخشی از او شده بود، عمیق‌ترین بخش، بخشی که بیشترین اهمیت را داشت."),
                    StoryParagraph("For in the end, the story was not about Kurtz but about all of us, about the darkness that we all carry, about the civilization that we have all built over that darkness, about the thin veil that separates us from the savagery within.", "زیرا در پایان، داستان درباره کورتز نبود بلکه درباره همه ما بود، درباره تاریکی‌ای که همه ما حمل می‌کنیم، درباره تمدنی که همه بر آن تاریکی ساخته‌ایم، درباره حجاب نازکی که ما را از وحشی‌گری درونمان جدا می‌کند."),
                    StoryParagraph("And the story was about the truth, the truth that we cannot face, the truth that we spend our lives avoiding, the truth that we can only approach through stories, through fictions, through lies that are also truths.", "و داستان درباره حقیقت بود، حقیقتی که نمی‌توانیم با آن روبرو شویم، حقیقتی که عمرمان را صرف اجتنابش می‌کنیم، حقیقتی که تنها از طریق داستان‌ها، از طریق داستان‌های خیالی، از طریق دروغ‌هایی که حقیقت هم هستند می‌توانیم به آن نزدیک شویم."),
                    StoryParagraph("And so the story ended, and the men on the Nellie went their separate ways, each carrying within them a seed of darkness, a seed that would grow, a seed that would change them, a seed that would make them human.", "و اینگونه داستان تمام شد و مردان روی نلی هر یک به راه خویش رفتند، هر یک در درونش بذری از تاریکی حمل می‌کرد، بذری که رشد می‌کرد، بذری که آنان را تغییر می‌داد، بذری که آنان را انسان می‌کرد."),
                    StoryParagraph("For that is the meaning of the story, if there is any meaning at all, that we are all creatures of darkness and light, that we are all capable of the most terrible cruelty and the most beautiful tenderness, that we are all, in the end, human.", "زیرا این معنای داستان است، اگر معنایی باشد، که همه ما مخلوقات تاریکی و نوریم، که همه ما قادر به هولناک‌ترین بی‌رحمی و زیباترین لطافتیم، که همه ما، در پایان، انسانیم."),
                    StoryParagraph("And the horror, the horror that Kurtz spoke of, is not something outside us, not something we can escape, but something within us, something that is part of who we are, something that we must learn to live with.", "و وحشت، وحشتی که کورتز از آن سخن گفت، چیزی بیرون از ما نیست، نه چیزی که می‌توانیم از آن بگریزیم، بلکه چیزی درون ما، چیزی که بخشی از آنچه هستیم است، چیزی که باید یاد بگیریم با آن زندگی کنیم."),
                    StoryParagraph("And so the story ended, and the darkness settled over the Thames, and the Nellie swung to her anchor, and the world continued to turn, indifferent to the truth that had been spoken, indifferent to the horror that had been named.", "و اینگونه داستان تمام شد و تاریکی بر تیمز نشست و نلی بر لنگرش تاب خورد و جهان به چرخیدن ادامه داد، بی‌تفاوت به حقیقتی که گفته شده بود، بی‌تفاوت به وحشتی که نام‌گذاری شده بود."),
                    StoryParagraph("The end.", "پایان."),
                    StoryParagraph("But the horror remains.", "اما وحشت باقی است.")
                )
            )
        )
    )

    // ═══════════════════════════════════════════════════════════
    // STORY 38 — Lord Jim (Joseph Conrad)
    // ═══════════════════════════════════════════════════════════
    private fun story38() = StoryContent(
        storyId = "adv_lord_jim",
        chapters = listOf(
            StoryChapter(
                number = 1, title = "The Patna", titlePersian = "پاتنا",
                paragraphs = listOf(
                    StoryParagraph("Jim was a young Englishman, tall and clean-limbed, with a frank face and blue eyes that looked straight at you, and he had come to the East to make his fortune on the sea, as many young Englishmen did in those days.", "جیم جوانی انگلیسی بود، بلندقد و خوش‌اندام، با چهره‌ای صادق و چشمانی آبی که مستقیم به تو نگاه می‌کرد، و به شرق آمده بود تا ثروتش را در دریا بسازد، همان‌طور که بسیاری از جوانان انگلیسی در آن روزگار می‌کردند."),
                    StoryParagraph("He had been trained as a seaman, had served on many ships, and had come at last to the Patna, an old steamer that carried pilgrims on their way to Mecca, a ship that was to become the scene of the central event of his life.", "او به‌عنوان دریانورد آموزش دیده بود، در کشتی‌های بسیاری خدمت کرده بود و سرانجام به پاتنا رسیده بود، کشتی بخار قدیمی که زائران را در راه مکه حمل می‌کرد، کشتی‌ای که به صحنه واقعه اصلی زندگی‌اش تبدیل می‌شد."),
                    StoryParagraph("The Patna was a miserable vessel, old and dirty and barely seaworthy, and it was crowded with eight hundred pilgrims, men and women and children who had sold everything they had to make this journey.", "پاتنا کشتی رقت‌انگیزی بود، قدیمی و کثیف و به‌سختی قابل دریا‌نوردی، و با هشتصد زائر پر شده بود، مردان و زنان و کودکانی که هر چه داشتند فروخته بودند تا این سفر را بکنند."),
                    StoryParagraph("They were not like the Europeans, these pilgrims, they did not have the same ideas about comfort or cleanliness or safety, but they had the same desires, the same hopes, the same fears, and they trusted the white men who had been given charge of their lives.", "آن‌ها مثل اروپایی‌ها نبودند، این زائران، ایده‌های مشابهی درباره راحتی یا پاکیزگی یا امنیت نداشتند، اما خواسته‌های مشابهی داشتند، امیدهای مشابه، ترس‌های مشابه، و به مردان سفیدپوستی که مسئول جانشان شده بودند اعتماد می‌کردند."),
                    StoryParagraph("Jim was the chief mate, the second in command, a young man of twenty-three with all the confidence of youth and all the inexperience that comes with it, a young man who had never faced a true test of courage.", "جیم افسر ارشد بود، نفر دوم فرماندهی، جوانی بیست‌وسه ساله با تمام اعتماد جوانی و تمام بی‌تجربگی که با آن می‌آید، جوانی که هرگز با آزمون واقعی شجاعت روبرو نشده بود."),
                    StoryParagraph("He had always imagined himself as a hero, as the kind of man who would rise to the occasion, who would do the right thing, who would never fail in the moment of crisis, and he had often dreamed of the moment when he would prove his courage.", "او همیشه خود را قهرمانی تصور کرده بود، از آن نوع مردانی که در لحظه به مناسبت می‌رسند، کار درست را می‌کنند، هرگز در لحظه بحران شکست نمی‌خورند، و اغلب لحظه‌ای را که شجاعتش را ثابت می‌کند در خواب می‌دید."),
                    StoryParagraph("But he had never been tested, he had never been put in a situation where his courage was required, and so his self-image remained untested, a hope rather than a certainty, a dream rather than a reality.", "اما هرگز آزموده نشده بود، هرگز در موقعیتی قرار نگرفته بود که شجاعتش لازم شود، و بنابراین تصویرش از خودش آزموده‌نشده باقی ماند، امیدی بیشتر از یک یقین، رؤیایی بیشتر از یک واقعیت."),
                    StoryParagraph("And then came the night when the Patna struck something in the darkness, something that tore a hole in her hull, something that would sink her within minutes, and Jim found himself facing the test he had always dreamed of.", "و سپس شبی آمد که پاتنا در تاریکی به چیزی خورد، چیزی که سوراخی در بدنه‌اش ایجاد کرد، چیزی که او را در چند دقیقه غرق می‌کرد، و جیم خود را در برابر آزمونی یافت که همیشه در خوابش می‌دید."),
                    StoryParagraph("The ship began to list, the water began to pour in, and the captain and the crew, the men who should have been calm and steady, the men who should have organized the rescue of the pilgrims, panicked.", "کشتی شروع به کج شدن کرد، آب شروع به ریختن کرد، و ناخدا و خدمه، مردانی که باید آرام و ثابت می‌ماندند، مردانی که باید نجات زائران را سازمان می‌دادند، وحشت کردند."),
                    StoryParagraph("They ran to the lifeboats, they abandoned the ship, they abandoned the pilgrims, they abandoned everything and everyone except themselves, and Jim, after a moment of hesitation, after a moment of terrible struggle, ran with them.", "آن‌ها به قایق‌های نجات دویدند، کشتی را رها کردند، زائران را رها کردند، همه چیز و همه کس را جز خودشان رها کردند، و جیم، پس از لحظه‌ای تردید، پس از لحظه‌ای مبارزه هولناک، با آنان دوید."),
                    StoryParagraph("He jumped into the lifeboat, he abandoned the ship, he abandoned the pilgrims, he abandoned the person he had thought he was, and in that moment he became someone else, someone he did not recognize, someone he would spend the rest of his life trying to become again.", "او به قایق نجات پرید، کشتی را رها کرد، زائران را رها کرد، آنکه تصور می‌کرد هست را رها کرد، و در آن لحظه کسی دیگر شد، کسی که نمی‌شناخت، کسی که باقی عمرش تلاش می‌کرد دوباره بشود."),
                    StoryParagraph("But the Patna did not sink, the pilgrims did not drown, the ship was found the next day, still afloat, still crowded with the living and the dead, and the world learned what Jim and the others had done.", "اما پاتنا غرق نشد، زائران غرق نشدند، کشتی روز بعد پیدا شد، هنوز شناور، هنوز پر از زنده و مرده، و جهان فهمید جیم و دیگران چه کرده بودند."),
                    StoryParagraph("They were brought to trial, the captain and the crew, and Jim was there with them, the youngest of them all, the one who had perhaps the most to lose, the one who would never be able to forget what he had done.", "آن‌ها به دادگاه آورده شدند، ناخدا و خدمه، و جیم با آنان بود، جوان‌ترینشان، کسی که شاید بیشترین چیز را برای از دست دادن داشت، کسی که هرگز نمی‌توانست فراموش کند چه کرده بود."),
                    StoryParagraph("The trial was held in a court in the East, and the room was full of people, men of the sea, men who had been tested in their own ways, men who had not run from their duty, and they looked at Jim with a mixture of pity and contempt.", "دادگاه در دادگاهی در شرق برگزار شد، و اتاق پر از مردم بود، مردان دریا، مردانی که به شیوه‌های خودشان آزموده شده بودند، مردانی که از وظیفه‌شان نگریخته بودند، و با ترکیبی از ترحم و تحقیر به جیم نگاه می‌کردند."),
                    StoryParagraph("Jim sat in the dock, his face pale, his eyes lowered, and he did not try to defend himself, he did not try to explain, he did not try to justify what he had done, for he knew that there was no justification.", "جیم در قفس متهمان نشست، صورتش رنگ‌پریده، چشمانش پایین، و تلاش نکرد از خودش دفاع کند، تلاش نکرد توضیح دهد، تلاش نکرد آنچه کرده بود را توجیه کند، زیرا می‌دانست توجیهی وجود ندارد."),
                    StoryParagraph("And in the audience, watching the trial, was a man named Marlow, a sea captain, a man who had seen much of the world and who recognized in Jim something of himself, something of every man, something of the universal human condition.", "و در میان تماشاگران، در حال تماشای دادگاه، مردی به نام مارلو بود، ناخدای دریا، مردی که بسیاری از جهان را دیده بود و در جیم چیزی از خودش تشخیص داد، چیزی از هر مردی، چیزی از وضعیت بشری جهانی."),
                    StoryParagraph("Marlow would later say that he had never seen a man so completely alone as Jim was in that courtroom, so completely isolated by what he had done, so completely exposed to the judgment of others.", "مارلو بعدها می‌گفت هرگز مردی را به این کاملی تنها ندیده بود که جیم در آن دادگاه بود، چنان کاملاً منزوی شده توسط آنچه کرده بود، چنان کاملاً در معرض داوری دیگران."),
                    StoryParagraph("And yet, Marlow would also say that he had never seen a man so completely human, so completely representative of the human struggle, of the human failure, of the human hope.", "و با این حال، مارلو همچنین می‌گفت هرگز مردی را به این کاملی انسان ندیده بود، چنان کاملاً نماینده مبارزه انسانی، شکست انسانی، امید انسانی."),
                    StoryParagraph("For Jim was not merely a coward, not merely a man who had failed a test of courage, but a man who had been forced to confront the truth about himself, the truth that all of us hide from, the truth that we are not what we imagine ourselves to be.", "زیرا جیم تنها بزدلی نبود، تنها مردی که در آزمون شجاعت شکست خورده بود، بلکه مردی بود که مجبور شده بود با حقیقت درباره خودش روبرو شود، حقیقتی که همه ما از آن پنهان می‌شویم، حقیقتی که آنچه تصور می‌کنیم نیستیم."),
                    StoryParagraph("The trial ended, Jim was stripped of his certificate, he was no longer a seaman, he was no longer a man with a profession, he was no longer a man with a future, he was simply a man with a past.", "دادگاه پایان یافت، جیم گواهی‌نامه‌اش را از دست داد، دیگر دریانورد نبود، دیگر مردی با حرفه نبود، دیگر مردی با آینده نبود، تنها مردی با گذشته بود."),
                    StoryParagraph("And this, Marlow understood, was the true punishment, not the loss of the certificate, not the judgment of the court, but the loss of the self, the loss of the person Jim had thought he was, the loss of the identity that had given his life meaning.", "و مارلو فهمید این همان مجازات واقعی بود، نه از دست دادن گواهی‌نامه، نه داوری دادگاه، بلکه از دست دادن خود، از دست دادن شخصی که جیم فکر می‌کرد هست، از دست دادن هویتی که به زندگی‌اش معنا بخشیده بود."),
                    StoryParagraph("Jim would spend the rest of his life trying to recover that self, trying to prove that he was not what he had done, trying to find a way to be a hero after having been a coward.", "جیم باقی عمرش را صرف تلاش برای بازیافتن آن خود می‌کرد، تلاش می‌کرد ثابت کند آنچه کرده نیست، تلاش می‌کرد راهی بیابد تا پس از بزدل بودن، قهرمان باشد."),
                    StoryParagraph("And that, Marlow said, is the story of Lord Jim, a story of a man who failed, and who spent his life trying to overcome that failure, and who perhaps, in the end, succeeded in a way that no one could have predicted.", "و مارلو گفت این داستان لرد جیم است، داستان مردی که شکست خورد و عمرش را صرف غلبه بر آن شکست کرد و شاید، در پایان، به شیوه‌ای که هیچ‌کس نمی‌توانست پیش‌بینی کند موفق شد."),
                    StoryParagraph("And so began the story of Lord Jim, a story that Marlow would tell many times, to many people, in many places, for it was a story that he could not forget, a story that had become a part of him.", "و اینگونه داستان لرد جیم آغاز شد، داستانی که مارلو بارها تعریف می‌کرد، برای افراد بسیاری، در جاهای بسیاری، زیرا داستانی بود که نمی‌توانست فراموشش کند، داستانی که بخشی از او شده بود."),
                    StoryParagraph("For in telling the story of Jim, Marlow was also telling the story of himself, and the story of every human being who has ever failed, and the story of every human being who has ever tried to rise above their failure.", "زیرا با تعریف داستان جیم، مارلو داستان خودش را هم تعریف می‌کرد، و داستان هر انسانی که هرگز شکست خورده، و داستان هر انسانی که هرگز تلاش کرده از شکستش فراتر رود."),
                    StoryParagraph("And that, perhaps, is the meaning of Lord Jim, that we are all Jim, that we all fail, that we all spend our lives trying to overcome our failures, and that some of us, in the end, succeed.", "و این، شاید، معنای لرد جیم است، که همه ما جیم هستیم، که همه ما شکست می‌خوریم، که همه ما عمرمان را صرف غلبه بر شکست‌هایمان می‌کنیم، و برخی از ما، در پایان، موفق می‌شویم."),
                    StoryParagraph("And so ended the first part of Jim's story, with the trial, with the judgment, with the beginning of a lifetime of atonement.", "و اینگونه بخش نخست داستان جیم با دادگاه، با داوری، با آغاز عمری کفاره به پایان رسید.")
                )
            ),
            StoryChapter(
                number = 2, title = "The East", titlePersian = "شرق",
                paragraphs = listOf(
                    StoryParagraph("After the trial, Jim wandered the East, moving from port to port, from job to job, from place to place, always trying to escape from his past, always trying to find a new beginning.", "پس از دادگاه، جیم در شرق سرگردان شد، از بندری به بندر، از شغلی به شغل، از جایی به جا، همیشه تلاش می‌کرد از گذشته‌اش بگریزد، همیشه تلاش می‌کرد آغازی جدید بیابد."),
                    StoryParagraph("He could not stay in one place for long, for wherever he went, he found men who had heard of the Patna, men who knew what he had done, men who looked at him with that same mixture of pity and contempt that he had seen in the courtroom.", "نمی‌توانست مدت طولانی در یک جا بماند، زیرا هر جا می‌رفت، مردانی می‌یافت که از پاتنا شنیده بودند، مردانی که می‌دانستند چه کرده، مردانی که با همان ترکیب ترحم و تحقیر به او نگاه می‌کردند که در دادگاه دیده بود."),
                    StoryParagraph("He took jobs that no one else wanted, jobs that kept him away from other men, jobs that allowed him to be alone with his thoughts, jobs that allowed him to punish himself in his own way.", "شغل‌هایی می‌گرفت که هیچ‌کس دیگری نمی‌خواست، شغل‌هایی که او را از مردان دیگر دور نگه می‌داشت، شغل‌هایی که به او اجازه می‌داد با افکارش تنها باشد، شغل‌هایی که به او اجازه می‌داد به شیوه خودش خودش را مجازات کند."),
                    StoryParagraph("He worked as a water clerk, as a ship chandler, as a stevedore, as anything that would keep him from the sea, for he could not face the sea again, could not face the ships, could not face the reminder of what he had done.", "او به‌عنوان کارمند آب، به‌عنوان فروشنده کشتی، به‌عنوان باربر بندر، به‌عنوان هر چیزی که او را از دریا دور نگه دارد کار می‌کرد، زیرا نمی‌توانست دوباره با دریا روبرو شود، نمی‌توانست با کشتی‌ها روبرو شود، نمی‌توانست با یادآوری آنچه کرده روبرو شود."),
                    StoryParagraph("And yet, the sea called to him, the sea that had been his life, the sea that had been his love, the sea that had been his identity, and he could not resist the call, he could not stay away from the ships, he could not stay away from the water.", "و با این حال، دریا او را می‌خواند، دریایی که زندگی‌اش بوده، دریایی که عشقش بوده، دریایی که هویتش بوده، و نمی‌توانست در برابر این خواندن مقاومت کند، نمی‌توانست از کشتی‌ها دور بماند، نمی‌توانست از آب دور بماند."),
                    StoryParagraph("And so he returned to the sea, again and again, each time hoping that this time would be different, each time hoping that this time he would prove himself, each time hoping that this time he would find peace.", "و اینگونه به دریا بازگشت، بارها و بارها، هر بار امیدوار بود این بار متفاوت باشد، هر بار امیدوار بود این بار خودش را ثابت کند، هر بار امیدوار بود این بار آرامش بیابد."),
                    StoryParagraph("But peace did not come, for the past was always with him, the memory of the Patna, the memory of the jump, the memory of the abandonment, the memory of the failure that had defined him.", "اما آرامش نیامد، زیرا گذشته همیشه با او بود، خاطره پاتنا، خاطره پرش، خاطره رها کردن، خاطره شکستی که او را تعریف کرده بود."),
                    StoryParagraph("He tried to forget, he tried to drown the memory in work, in drink, in movement, in anything that would distract him from himself, but nothing worked, for the memory was not in the world but in his own mind.", "تلاش کرد فراموش کند، تلاش کرد خاطره را در کار، در نوشیدن، در حرکت، در هر چیزی که حواسش را از خودش پرت کند غرق کند، اما هیچ‌چیز کار نکرد، زیرا خاطره در جهان نبود بلکه در ذهن خودش بود."),
                    StoryParagraph("And then, one day, he met Marlow again, in a port in the East, in a café overlooking the harbor, and Marlow, who had been following Jim's career with interest, offered to help him.", "و سپس، یک روز، دوباره مارلو را ملاقات کرد، در بندری در شرق، در کافه‌ای مشرف به بندر، و مارلو، که با علاقه حرفه جیم را دنبال کرده بود، پیشنهاد کمک به او کرد."),
                    StoryParagraph("Marlow had heard of a man named Stein, a wealthy trader who lived in the interior, a man who collected butterflies and antiquities, a man who was looking for an assistant, a man who might be willing to give Jim a chance.", "مارلو از مردی به نام اشتاین شنیده بود، تاجر ثروتمندی که در داخل کشور زندگی می‌کرد، مردی که پروانه‌ها و عتیقه‌ها جمع می‌کرد، مردی که به دنبال دستیار بود، مردی که شاید مایل باشد به جیم فرصتی بدهد."),
                    StoryParagraph("Jim agreed to meet Stein, and the meeting changed his life, for Stein saw something in Jim that others had not seen, saw not the coward but the man who was trying to overcome his cowardice, not the failure but the man who was trying to rise above his failure.", "جیم موافقت کرد اشتاین را ملاقات کند و این ملاقات زندگی‌اش را تغییر داد، زیرا اشتاین چیزی در جیم دید که دیگران ندیده بودند، نه بزدل بلکه مردی که تلاش می‌کرد بر بزدلی‌اش غلبه کند، نه شکست‌خواره بلکه مردی که تلاش می‌کرد از شکستش فراتر رود."),
                    StoryParagraph("Stein was a man of great wisdom and great experience, a man who had lived in the East for many years, a man who had come to understand the people and the customs of the land, a man who had learned to see beneath the surface of things.", "اشتاین مردی با خرد فراوان و تجربه فراوان بود، مردی که سال‌ها در شرق زندگی کرده بود، مردی که شروع کرده بود به فهمیدن مردم و آداب این سرزمین، مردی که آموخته بود زیر سطح چیزها را ببیند."),
                    StoryParagraph("Stein spoke to Jim about a man who falls into the sea, and who must choose between sinking and swimming, and who must learn that the sea is not his enemy but his home, and that he must trust it if he is to survive.", "اشتاین با جیم از مردی سخن گفت که به دریا می‌افتد و باید بین غرق شدن و شنا کردن انتخاب کند و باید بیاموزد که دریا دشمنش نیست بلکه خانه‌اش است و اگر می‌خواهد زنده بماند باید به آن اعتماد کند."),
                    StoryParagraph("Jim understood the metaphor, understood that Stein was telling him that he must stop fighting his past and start accepting it, must stop running from his failure and start learning from it, must stop being a victim and start being a man.", "جیم استعاره را فهمید، فهمید اشتاین به او می‌گفت باید از جنگیدن با گذشته‌اش دست بکشد و پذیرشش را آغاز کند، باید از فرار از شکستش دست بکشد و از آن بیاموزد، باید از قربانی بودن دست بکشد و مرد بودن را آغاز کند."),
                    StoryParagraph("Stein offered Jim a position as his agent in Patusan, a remote trading post in the interior of the East, a place that no one else wanted to go, a place where a man could start over, a place where a man could prove himself.", "اشتاین به جیم موقعیتی به‌عنوان نماینده‌اش در پاتوسان پیشنهاد داد، پاسگاه تجاری دورافتاده در داخل شرق، جایی که هیچ‌کس دیگری نمی‌خواست برود، جایی که مردی می‌توانست از نو شروع کند، جایی که مردی می‌توانست خودش را ثابت کند."),
                    StoryParagraph("Jim accepted the position, and he went to Patusan, and there he found what he had been seeking, a chance to be the man he had always imagined himself to be, a chance to prove that he was not what he had done.", "جیم این موقعیت را پذیرفت و به پاتوسان رفت، و آنجا آنچه را می‌جست یافت، فرصتی برای بودن مردی که همیشه خود را تصور می‌کرد، فرصتی برای اثبات اینکه آنچه کرده نیست."),
                    StoryParagraph("Patusan was a place of great beauty and great danger, a place of jungles and rivers and mountains, a place of native princes and warring tribes, a place where the rule of law had not yet arrived, a place where a man could make his own rules.", "پاتوسان جایی پر از زیبایی فراوان و خطر فراوان بود، جایی از جنگل‌ها و رودها و کوه‌ها، جایی از شاهزادگان بومی و قبایل جنگنده، جایی که هنوز قانون به آن نرسیده بود، جایی که مردی می‌توانست قوانین خودش را بسازد."),
                    StoryParagraph("And there, in Patusan, Jim found himself, found the man he had always wanted to be, found the courage that he had thought he had lost, found the strength to face whatever came, found the peace that had eluded him for so long.", "و آنجا، در پاتوسان، جیم خودش را یافت، مردی که همیشه می‌خواست باشد را یافت، شجاعتی که فکر می‌کرد از دست داده را یافت، قدرتی برای روبرو شدن با هر چه می‌آید یافت، آرامشی که اینقدر طولانی از او گریخته بود یافت."),
                    StoryParagraph("He became the leader of the people of Patusan, the friend of the local prince, the protector of the weak, the enemy of the wicked, the man who brought peace to a land that had known only war.", "او رهبر مردم پاتوسان شد، دوست شاهزاده محلی، محافظ ضعیفان، دشمن شریران، مردی که به سرزمینی که تنها جنگ شناخته بود صلح آورد."),
                    StoryParagraph("And the people of Patusan called him Tuan Jim, which means Lord Jim, for he had become their lord, their protector, their savior, the man who had come from nowhere and who had become everything to them.", "و مردم پاتوسان او را توان جیم نامیدند، که یعنی لرد جیم، زیرا او اربابشان شده بود، محافظشان، نجات‌دهنده‌شان، مردی که از هیچ‌جا آمده بود و همه چیز آنان شده بود."),
                    StoryParagraph("And so ended the second part of Jim's story, with the journey to the East, with the arrival in Patusan, with the beginning of a new life in a new land.", "و اینگونه بخش دوم داستان جیم با سفر به شرق، با ورود به پاتوسان، با آغاز زندگی نو در سرزمینی نو به پایان رسید.")
                )
            ),
            StoryChapter(
                number = 3, title = "Patusan", titlePersian = "پاتوسان",
                paragraphs = listOf(
                    StoryParagraph("Patusan was a land of great beauty and great danger, a land of rushing rivers and thick jungles, a land of high mountains and deep valleys, a land that had been forgotten by the world and that had forgotten the world in turn.", "پاتوسان سرزمینی پر از زیبایی فراوان و خطر فراوان بود، سرزمینی از رودهای خروشان و جنگل‌های انبوه، سرزمینی از کوه‌های بلند و دره‌های عمیق، سرزمینی که جهان فراموشش کرده بود و خودش هم جهان را فراموش کرده بود."),
                    StoryParagraph("The people of Patusan were a proud and warlike people, divided into tribes that had been fighting each other for generations, tribes that had learned to hate and to fear and to kill before they had learned to love and to trust and to live.", "مردم پاتوسان مردمی مغرور و جنگجو بودند، تقسیم شده به قبایلی که نسل‌ها با هم می‌جنگیدند، قبایلی که یاد گرفته بودند پیش از یاد گرفتن عشق و اعتماد و زندگی، نفرت و ترس و کشتن را."),
                    StoryParagraph("There was the old prince, the rightful ruler, a man who had been deposed by his own nephew, a man who had been forced to flee to the mountains, a man who still dreamed of reclaiming his throne.", "شاهزاده پیر بود، فرمانروای قانونی، مردی که توسط برادرزاده خودش خلع شده بود، مردی که مجبور شده بود به کوه‌ها بگریزد، مردی که هنوز در خواب پس گرفتن تختش را می‌دید."),
                    StoryParagraph("There was the nephew, the usurper, a man of cruelty and cunning, a man who had taken the throne by force, a man who ruled through fear, a man who would do anything to keep what he had stolen.", "برادرزاده بود، غاصب، مردی از بی‌رحمی و حیله‌گری، مردی که تخت را با زور گرفته بود، مردی که از طریق ترس حکومت می‌کرد، مردی که هر کاری می‌کرد تا آنچه دزدیده بود را نگه دارد."),
                    StoryParagraph("There was the other chief, the Bugis chief, a man of honor and courage, a man who had come to Patusan years before and who had stayed, a man who had become a friend to the old prince and an enemy to the usurper.", "رئیس دیگر بود، رئیس بوگیس، مردی از شرافت و شجاعت، مردی که سال‌ها پیش به پاتوسان آمده بود و مانده بود، مردی که دوست شاهزاده پیر و دشمن غاصب شده بود."),
                    StoryParagraph("And there was Jim, the stranger, the white man who had come from nowhere, who had been given a trading post by Stein, who had been asked to bring peace to this troubled land, who had been given a chance to prove himself.", "و جیم بود، غریبه، مرد سفیدپوستی که از هیچ‌جا آمده بود، که اشتاین پاسگاهی تجاری به او داده بود، که از او خواسته شده بود صلح به این سرزمین پرآشوب بیاورد، که فرصتی برای اثبات خود یافته بود."),
                    StoryParagraph("Jim arrived in Patusan with nothing but his reputation, and his reputation was not good, for the story of the Patna had followed him even here, to this remote corner of the world, and the people of Patusan had heard that he was a coward.", "جیم با هیچ جز آبرویش به پاتوسان رسید و آبرویش خوب نبود، زیرا داستان پاتنا حتی به اینجا هم دنبالش کرده بود، به این گوشه دورافتاده جهان، و مردم پاتوسان شنیده بودند که او بزدلی است."),
                    StoryParagraph("But Jim did not try to hide his past, he did not try to deny what he had done, he did not try to pretend that he was someone he was not, and this honesty, this willingness to face his own shame, impressed the people of Patusan.", "اما جیم تلاش نکرد گذشته‌اش را پنهان کند، تلاش نکرد آنچه کرده را انکار کند، تلاش نکرد تظاهر کند کسی است که نیست، و این صداقت، این آمادگی برای رویارویی با شرم خودش، مردم پاتوسان را تحت تأثیر قرار داد."),
                    StoryParagraph("They saw in him a man who had suffered, a man who had been tested, a man who had failed and who had not given up, a man who had come to their land to make a new life, and they respected him for it.", "آن‌ها در او مردی دیدند که رنج کشیده بود، مردی که آزموده شده بود، مردی که شکست خورده بود و تسلیم نشده بود، مردی که به سرزمینشان آمده بود تا زندگی نویی بسازد، و برای این به او احترام گذاشتند."),
                    StoryParagraph("And Jim, in turn, respected them, he did not treat them as inferiors, as the other white men did, he did not treat them as children, as the other white men did, he treated them as equals, as men, as human beings.", "و جیم هم به آن‌ها احترام گذاشت، آن‌ها را مثل دیگر مردان سفیدپوست کهتر نمی‌دید، مثل دیگر مردان سفیدپوست کودک نمی‌دید، آن‌ها را برابر می‌دید، به‌عنوان مردان، به‌عنوان انسان‌ها."),
                    StoryParagraph("He learned their language, he learned their customs, he learned their stories, he learned to see the world through their eyes, and in doing so he became one of them, or as close to one of them as a white man could become.", "زبانشان را آموخت، آدابشان را آموخت، داستان‌هایشان را آموخت، آموخت جهان را از چشمان آنان ببیند، و در این کار یکی از آنان شد، یا تا آنجا که یک مرد سفیدپوست می‌توانست یکی از آنان شود."),
                    StoryParagraph("He took a wife, a woman named Jewel, the daughter of a Dutch trader and a native woman, a woman who had been raised in Patusan, a woman who knew the land and its people, a woman who loved Jim with all her heart.", "زنی گرفت، زنی به نام جول، دختر تاجری هلندی و زنی بومی، زنی که در پاتوسان بزرگ شده بود، زنی که سرزمین و مردمش را می‌شناخت، زنی که جیم را با تمام قلبش دوست داشت."),
                    StoryParagraph("Jewel had been warned about white men, had been told that they always leave, had been told that they never stay, had been told that they always break their promises, and she had believed these warnings until she met Jim.", "جول درباره مردان سفیدپوست هشدار داده شده بود، به او گفته شده بود که همیشه می‌روند، به او گفته شده بود که هرگز نمی‌مانند، به او گفته شده بود که همیشه قول‌هایشان را می‌شکنند، و او این هشدارها را باور داشت تا وقتی جیم را ملاقات کرد."),
                    StoryParagraph("Jim promised her that he would never leave, that he would stay with her forever, that he would never abandon her as he had abandoned the pilgrims on the Patna, and she believed him, and she loved him, and she trusted him.", "جیم به او قول داد که هرگز نمی‌رود، که برای همیشه با او می‌ماند، که هرگز رهایش نمی‌کند همان‌طور که زائران پاتنا را رها کرده بود، و او باورش کرد، و او را دوست داشت، و به او اعتماد کرد."),
                    StoryParagraph("And for a time, Jim was happy, happier than he had ever been, for he had found a place where he could be himself, where he could be the man he wanted to be, where his past did not define him, where his future was his own.", "و برای مدتی، جیم خوشحال بود، خوشحال‌تر از آنچه تا به حال بوده، زیرا جایی یافته بود که می‌توانست خودش باشد، مردی که می‌خواست باشد، جایی که گذشته‌اش تعریفش نمی‌کرد، جایی که آینده‌اش از خودش بود."),
                    StoryParagraph("He helped the old prince, he fought the usurper, he brought peace to Patusan, he became the leader the people needed, he became the man the people had been waiting for, he became Tuan Jim, Lord Jim.", "او به شاهزاده پیر کمک کرد، با غاصب جنگید، صلح به پاتوسان آورد، رهبری شد که مردم نیاز داشتند، مردی شد که مردم منتظرش بودند، توان جیم شد، لرد جیم."),
                    StoryParagraph("And the people of Patusan loved him, and the people of Patusan trusted him, and the people of Patusan would have followed him anywhere, for he had become their hope, their protector, their lord.", "و مردم پاتوسان دوستش داشتند، و مردم پاتوسان به او اعتماد داشتند، و مردم پاتوسان هر جا می‌رفت دنبالش می‌کردند، زیرا او امیدشان شده بود، محافظشان، اربابشان."),
                    StoryParagraph("But even in Patusan, even in this remote corner of the world, Jim could not escape his past, for the past is not a place but a time, and time cannot be escaped, and Jim carried his past within him wherever he went.", "اما حتی در پاتوسان، حتی در این گوشه دورافتاده جهان، جیم نمی‌توانست از گذشته‌اش بگریزد، زیرا گذشته نه مکان است بلکه زمان، و از زمان نمی‌توان گریخت، و جیم گذشته‌اش را هر جا می‌رفت با خود حمل می‌کرد."),
                    StoryParagraph("And so, one day, a man arrived in Patusan, a man named Brown, a man who had come to cause trouble, a man who would test Jim as he had never been tested before.", "و اینگونه، یک روز، مردی به پاتوسان رسید، مردی به نام براون، مردی که آمده بود تا دردسر ایجاد کند، مردی که جیم را می‌آزمود همان‌طور که هرگز قبلاً آزموده نشده بود."),
                    StoryParagraph("Brown was a pirate, a thief, a murderer, a man who had been driven out of every port, a man who was looking for a place to hide, a place to rest, a place to plan his next crime.", "براون دزد دریایی بود، دزد، قاتل، مردی که از هر بندری رانده شده بود، مردی که دنبال جایی برای پنهان شدن می‌گشت، جایی برای استراحت، جایی برای نقشه کشیدن جنایت بعدی‌اش."),
                    StoryParagraph("And so ended the third part of Jim's story, with the arrival of the man who would test him, the man who would force him to choose between his past and his present, between who he was and who he had become.", "و اینگونه بخش سوم داستان جیم با ورود مردی که او را می‌آزمود به پایان رسید، مردی که او را مجبور می‌کرد بین گذشته و حالش انتخاب کند، بین آنکه بود و آنکه شده بود.")
                )
            ),
            StoryChapter(
                number = 4, title = "Brown", titlePersian = "براون",
                paragraphs = listOf(
                    StoryParagraph("Brown arrived in Patusan with a small band of followers, men as desperate and as dangerous as himself, men who had nothing to lose, men who would do anything to survive, men who had long since abandoned any pretense of decency.", "براون با گروه کوچکی از پیروانش به پاتوسان رسید، مردانی به همان اندازه ناامید و خطرناک مثل خودش، مردانی که هیچ چیز برای از دست دادن نداشتند، مردانی که هر کاری برای زنده ماندن می‌کردند، مردانی که مدت‌ها بود هر تظاهر به نجابت را رها کرده بودند."),
                    StoryParagraph("They came up the river in a small boat, they came in the night, they came with guns and knives and a willingness to use them, and they came to Patusan because they had heard that here, at last, there might be a place to hide.", "آن‌ها در قایق کوچکی در رود آمدند، در شب آمدند، با تفنگ و چاقو و آمادگی استفاده از آن‌ها آمدند، و به پاتوسان آمدند چون شنیده بودند اینجا، سرانجام، شاید جایی برای پنهان شدن باشد."),
                    StoryParagraph("But Patusan was not empty, Patusan was not ungoverned, Patusan was not a place where outlaws could do as they pleased, for Patusan had a lord now, Patusan had Jim, and Jim would not allow these men to bring their violence to his land.", "اما پاتوسان خالی نبود، پاتوسان بی‌حکومت نبود، پاتوسان جایی نبود که یاغیان هر چه می‌خواهند بکنند، زیرا پاتوسان اکنون اربابی داشت، پاتوسان جیم را داشت، و جیم اجازه نمی‌داد این مردان خشونتشان را به سرزمینش بیاورند."),
                    StoryParagraph("The chief Doramin, the Bugis chief who had become Jim's friend and ally, warned Jim about Brown, told him that the man was dangerous, told him that the man could not be trusted, told him that the man should be killed.", "رئیس دورامین، رئیس بوگیس که دوست و متحد جیم شده بود، جیم را درباره براون هشدار داد، به او گفت آن مرد خطرناک است، به او گفت نمی‌شود به آن مرد اعتماد کرد، به او گفت آن مرد باید کشته شود."),
                    StoryParagraph("But Jim did not want to kill Brown, Jim did not want any more killing, Jim had seen enough killing in his life, Jim wanted to end the cycle of violence, Jim wanted to prove that there was another way.", "اما جیم نمی‌خواست براون را بکشد، جیم نمی‌خواست کشتار بیشتر، جیم به اندازه کافی کشتار در زندگی‌اش دیده بود، جیم می‌خواست چرخه خشونت را پایان دهد، جیم می‌خواست ثابت کند راه دیگری هست."),
                    StoryParagraph("Jim went to meet Brown, alone, unarmed, trusting in his own courage and in his own ability to persuade, trusting in the man he had become and the man he wanted to be, and this trust, this confidence, would prove to be his undoing.", "جیم برای ملاقات براون رفت، تنها، بی‌سلاح، اعتماد به شجاعت خودش و توانایی خودش در متقاعد کردن، اعتماد به مردی که شده بود و مردی که می‌خواست باشد، و این اعتماد، این اطمینان، به نابودی‌اش تبدیل می‌شد."),
                    StoryParagraph("Brown was surprised to see Jim come alone, Brown was surprised to see Jim come unarmed, Brown was surprised to see Jim come without guards, and Brown, being what he was, saw in this not courage but weakness.", "براون از دیدن اینکه جیم تنها آمده تعجب کرد، از دیدن اینکه جیم بی‌سلاح آمده تعجب کرد، از دیدن اینکه جیم بدون محافظ آمده تعجب کرد، و براون، همان‌طور که بود، در این نه شجاعت بلکه ضعف دید."),
                    StoryParagraph("Jim spoke to Brown, spoke of peace, spoke of the possibility of a new life, spoke of the chance to start over, spoke of forgiveness, spoke of understanding, spoke of all the things that Jim wanted to believe were possible in the world.", "جیم با براون صحبت کرد، از صلح گفت، از امکان زندگی نو گفت، از فرصت شروع دوباره گفت، از بخشش گفت، از فهمیدن گفت، از تمام چیزهایی گفت که جیم می‌خواست باور کند در جهان ممکن‌اند."),
                    StoryParagraph("Brown listened, Brown pretended to listen, Brown nodded and smiled and said all the right things, Brown made Jim believe that he had understood, Brown made Jim believe that he had changed, Brown made Jim believe that there was hope even for a man like him.", "براون گوش داد، براون تظاهر کرد گوش می‌دهد، براون سر تکان داد و لبخند زد و همه چیزهای درست را گفت، براون جیم را باوراند که فهمیده، جیم را باوراند که تغییر کرده، جیم را باوراند که حتی برای مردی مثل او امیدی هست."),
                    StoryParagraph("But Brown had not understood, Brown had not changed, Brown was only pretending, Brown was only waiting for his chance, Brown was only looking for a way to escape and to cause as much damage as possible on his way out.", "اما براون نفهمیده بود، براون تغییر نکرده بود، براون فقط تظاهر می‌کرد، براون فقط منتظر فرصتش بود، براون فقط دنبال راهی برای فرار و ایجاد بیشترین خسارت ممکن در راه خروجش بود."),
                    StoryParagraph("Jim let Brown go, Jim let Brown and his men leave Patusan, Jim gave them provisions, Jim gave them a boat, Jim gave them safe passage, and in doing so, Jim made the greatest mistake of his life.", "جیم گذاشت براون برود، جیم گذاشت براون و مردانش پاتوسان را ترک کنند، جیم به آنان تدارکات داد، جیم به آنان قایقی داد، جیم به آنان گذر امن داد، و در این کار، جیم بزرگ‌ترین اشتباه عمرش را کرد."),
                    StoryParagraph("For Brown, on his way out of Patusan, killed the son of Doramin, killed the young man who was the hope of the Bugis people, killed the boy who had been like a son to Jim himself.", "زیرا براون، در راه خروجش از پاتوسان، پسر دورامین را کشت، جوانی را کشت که امید مردم بوگیس بود، پسری را کشت که برای خود جیم مثل پسر بوده بود."),
                    StoryParagraph("When Jim learned what had happened, when Jim learned that his mercy had led to death, when Jim learned that his trust had been betrayed, he knew what he had to do.", "وقتی جیم فهمید چه اتفاقی افتاده، وقتی جیم فهمید که رحمش به مرگ منجر شده، وقتی جیم فهمید که اعتمادش خیانت شده بود، می‌دانست چه باید بکند."),
                    StoryParagraph("He went to Doramin, he went to the man whose son had been killed, he went to the man who had been his friend and ally, and he stood before him, and he waited.", "او به نزد دورامین رفت، به نزد مردی که پسرش کشته شده بود، به نزد مردی که دوست و متحدش بوده، و پیش رویش ایستاد، و منتظر ماند."),
                    StoryParagraph("Doramin looked at Jim, Doramin remembered the promises, Doramin remembered the trust, Doramin remembered the son he had lost, and Doramin knew what he had to do.", "دورامین به جیم نگاه کرد، دورامین قول‌ها را به یاد آورد، دورامین اعتماد را به یاد آورد، دورامین پسر از دست رفته‌اش را به یاد آورد، و دورامین می‌دانست چه باید بکند."),
                    StoryParagraph("Jim did not resist, Jim did not run, Jim did not try to explain, Jim did not try to justify, Jim simply stood there, and he waited, and he accepted what was coming.", "جیم مقاومت نکرد، جیم فرار نکرد، جیم تلاش نکرد توضیح دهد، جیم تلاش نکرد توجیه کند، جیم فقط آنجا ایستاد، و منتظر ماند، و پذیرفت آنچه می‌آمد."),
                    StoryParagraph("For Jim had finally understood what Stein had told him, had finally understood that a man must face the consequences of his actions, had finally understood that courage is not the absence of fear but the willingness to act in spite of it.", "زیرا جیم سرانجام فهمیده بود اشتاین به او چه گفته بود، سرانجام فهمیده بود که انسان باید با پیامدهای اعمالش روبرو شود، سرانجام فهمیده بود که شجاعت نبود ترس نیست بلکه آمادگی عمل کردن به رغم آن است."),
                    StoryParagraph("And he had finally understood that the only way to overcome a failure is to accept it, to embrace it, to make it a part of who you are, and to move forward.", "و سرانجام فهمیده بود که تنها راه غلبه بر شکست این است که آن را بپذیری، در آغوشش بگیری، بخشی از آنچه هستی بکنی، و به جلو حرکت کنی."),
                    StoryParagraph("Doramin raised his gun, Doramin aimed at Jim, Doramin fired, and Jim fell, and Jim died, and Jim died as the man he had always wanted to be, the man who faced his fate with courage, the man who did not run.", "دورامین تفنگش را بلند کرد، دورامین به جیم نشانه گرفت، دورامین شلیک کرد، و جیم افتاد، و جیم مرد، و جیم همان مردی مرد که همیشه می‌خواست باشد، مردی که با شجاعت با سرنوشتش روبرو شد، مردی که فرار نکرد."),
                    StoryParagraph("And so ended the fourth part of Jim's story, with the death of Lord Jim, with the atonement for his failure, with the final proof that he was not a coward after all.", "و اینگونه بخش چهارم داستان جیم با مرگ لرد جیم، با کفاره شکستش، با اثبات نهایی که اصلاً بزدل نبود به پایان رسید.")
                )
            ),
            StoryChapter(
                number = 5, title = "The Meaning", titlePersian = "معنا",
                paragraphs = listOf(
                    StoryParagraph("Marlow learned of Jim's death many months after it happened, learned of it from a letter, learned of it from a friend who had been in the East, learned of it and felt a strange mixture of sorrow and peace.", "مارلو ماه‌ها بعد از وقوعش از مرگ جیم مطلع شد، از نامه‌ای مطلع شد، از دوستی که در شرق بوده مطلع شد، مطلع شد و ترکیبی عجیب از اندوه و آرامش حس کرد."),
                    StoryParagraph("For Jim had finally found what he had been seeking, Marlow understood, had finally become what he had always wanted to be, had finally proven that he was not defined by his failure but by his response to it.", "زیرا جیم سرانجام آنچه را می‌جست یافته بود، مارلو فهمید، سرانجام آنچه همیشه می‌خواست باشد شده بود، سرانجام ثابت کرده بود که شکستش تعریفش نمی‌کند بلکه پاسخش به آن تعریفش می‌کند."),
                    StoryParagraph("And in that understanding, Marlow found a kind of hope, a hope that even the worst of us can be redeemed, a hope that even the greatest failures can be overcome, a hope that there is always a chance to become someone better.", "و در آن فهم، مارلو نوعی امید یافت، امیدی که حتی بدترین ما هم می‌تواند رستگار شود، امیدی که حتی بزرگ‌ترین شکست‌ها هم می‌تواند غلبه شود، امیدی که همیشه فرصتی برای بهتر شدن هست."),
                    StoryParagraph("Marlow had known Jim as a young man, had known him as a man who had failed, had known him as a man who had been broken by his failure, had known him as a man who had tried to run from his past.", "مارلو جیم را به‌عنوان جوانی شناخته بود، به‌عنوان مردی که شکست خورده بود شناخته بود، به‌عنوان مردی که توسط شکستش شکسته شده بود شناخته بود، به‌عنوان مردی که تلاش کرده بود از گذشته‌اش بگریزد شناخته بود."),
                    StoryParagraph("But Marlow had also seen Jim's potential, had seen the man Jim could become, had seen the courage that lay hidden beneath the cowardice, had seen the hope that lay hidden beneath the despair.", "اما مارلو پتانسیل جیم را هم دیده بود، مردی که جیم می‌توانست بشود را دیده بود، شجاعتی که زیر بزدلی پنهان بود را دیده بود، امیدی که زیر ناامیدی پنهان بود را دیده بود."),
                    StoryParagraph("And Marlow had been proven right, Marlow had seen what others had not seen, Marlow had understood what others had not understood, Marlow had known what others had not known.", "و مارلو حق به جانب ثابت شده بود، مارلو چیزی را دیده بود که دیگران ندیده بودند، چیزی را فهمیده بود که دیگران نفهمیده بودند، چیزی را دانسته بود که دیگران ندانسته بودند."),
                    StoryParagraph("For Jim had not been merely a coward, Jim had not been merely a failure, Jim had been a man, a man with all the weaknesses and all the strengths of his kind, a man who had fallen and who had risen again.", "زیرا جیم تنها بزدلی نبوده، جیم تنها شکست‌خواره‌ای نبوده، جیم مردی بوده، مردی با تمام ضعف‌ها و تمام قوت‌های نوعش، مردی که افتاده بود و دوباره برخاسته بود."),
                    StoryParagraph("And in that rising, in that willingness to face his fate, in that final act of courage, Jim had become something more than a man, had become a symbol, had become a lesson, had become an example for all who would follow.", "و در آن برخاستن، در آن آمادگی برای روبرو شدن با سرنوشتش، در آن عمل نهایی شجاعت، جیم به چیزی بیشتر از انسان تبدیل شده بود، به نمادی، به درسی، به نمونه‌ای برای همه کسانی که دنبال می‌کردند."),
                    StoryParagraph("Marlow thought often of Jim, thought of him in the years that followed, thought of him when he himself faced difficult choices, thought of him when he himself was tempted to run from his own fears.", "مارلو اغلب به جیم فکر می‌کرد، در سال‌های بعد به او فکر می‌کرد، وقتی خودش با انتخاب‌های دشوار روبرو می‌شد به او فکر می‌کرد، وقتی خودش وسوسه می‌شد از ترس‌هایش بگریزد به او فکر می‌کرد."),
                    StoryParagraph("And each time, Marlow would remember what Jim had done, would remember that Jim had faced his death with courage, would remember that Jim had died as the man he had always wanted to be, and Marlow would find in that memory the strength to go on.", "و هر بار، مارلو به یاد می‌آورد جیم چه کرده بود، به یاد می‌آورد که جیم با شجاعت با مرگش روبرو شده بود، به یاد می‌آورد که جیم همان مردی مرده بود که همیشه می‌خواست باشد، و مارلو در آن خاطره قوتی برای ادامه دادن می‌یافت."),
                    StoryParagraph("For that, Marlow understood, is what a hero is, not someone who is never afraid, not someone who never fails, not someone who is perfect, but someone who faces their fears, who accepts their failures, who continues to strive.", "زیرا مارلو فهمید قهرمان کسی است که هرگز نمی‌ترسد نه، هرگز شکست نمی‌خورد نه، کامل است نه، بلکه کسی که با ترس‌هایش روبرو می‌شود، شکست‌هایش را می‌پذیرد، به تلاش ادامه می‌دهد."),
                    StoryParagraph("Jim had been a hero in that sense, had been a hero in the only sense that matters, had been a hero because he had not given up, because he had kept trying, because he had refused to let his failure define him.", "جیم به آن معنا قهرمان بوده، به تنها معنایی که مهم است قهرمان بوده، قهرمان بوده چون تسلیم نشده، چون به تلاش ادامه داده، چون امتناع کرده از اینکه شکستش تعریفش کند."),
                    StoryParagraph("And Marlow hoped, hoped against hope, that others would learn from Jim's example, that others would find in his story the courage to face their own failures, that others would understand that it is never too late to become the person you want to be.", "و مارلو امیدوار بود، خلاف همه امیدها، که دیگران از نمونه جیم بیاموزند، که دیگران در داستانش شجاعت رویارویی با شکست‌های خودشان را بیابند، که دیگران بفهمند هرگز برای تبدیل شدن به کسی که می‌خواهی باشی دیر نیست."),
                    StoryParagraph("And so Marlow continued to tell Jim's story, to anyone who would listen, in any place where he found himself, in any circumstance that called for a reminder that even the fallen can rise.", "و اینگونه مارلو به تعریف داستان جیم ادامه داد، برای هر کس که گوش می‌داد، در هر جایی که خودش را می‌یافت، در هر شرایطی که یادآوری می‌طلبید که حتی افتادگان هم می‌توانند برخیزند."),
                    StoryParagraph("For the story of Jim was not merely the story of one man, not merely the story of one failure, not merely the story of one redemption, but the story of all of us, the story of the human condition.", "زیرا داستان جیم تنها داستان یک مرد نبود، تنها داستان یک شکست نبود، تنها داستان یک رستگاری نبود، بلکه داستان همه ما بود، داستان وضعیت بشری."),
                    StoryParagraph("For we all fail, we all fall, we all do things that we regret, we all carry within us the memory of our worst moments, and we all must find a way to live with those memories, to move forward, to become better.", "زیرا همه ما شکست می‌خوریم، همه ما می‌افتیم، همه ما کارهایی می‌کنیم که پشیمانشان هستیم، همه ما در درونمان خاطره بدترین لحظه‌هایمان را حمل می‌کنیم، و همه ما باید راهی برای زندگی با آن خاطرات بیابیم، برای حرکت به جلو، برای بهتر شدن."),
                    StoryParagraph("And Jim had found that way, had found it in Patusan, had found it in the love of a woman, had found it in the trust of a people, had found it in the final act of courage that had redeemed his life.", "و جیم آن راه را یافته بود، در پاتوسان یافته بود، در عشق زنی یافته بود، در اعتماد مردمی یافته بود، در عمل نهایی شجاعتی که زندگی‌اش را رستگار کرده بود یافته بود."),
                    StoryParagraph("And his story, the story that Marlow told again and again, was a reminder to all of us that we too can find that way, that we too can overcome our failures, that we too can become the people we want to be.", "و داستانش، داستانی که مارلو بارها و بارها تعریف می‌کرد، یادآوری‌ای برای همه ما بود که ما هم می‌توانیم آن راه را بیابیم، ما هم می‌توانیم بر شکست‌هایمان غلبه کنیم، ما هم می‌توانیم کسانی شویم که می‌خواهیم باشیم."),
                    StoryParagraph("And so the story of Lord Jim came to an end, or rather it came to a new beginning, for every ending is also a beginning, and every death is also a birth, and every failure is also an opportunity.", "و اینگونه داستان لرد جیم به پایان رسید، یا بهتر، به آغازی نو رسید، زیرا هر پایانی آغازی هم هست، و هر مرگی تولدی هم هست، و هر شکستی فرصتی هم هست."),
                    StoryParagraph("And so ended the fifth part of Jim's story, with the meaning of his life, with the lesson of his death, with the hope that his story would inspire others.", "و اینگونه بخش پنجم داستان جیم با معنای زندگی‌اش، با درس مرگش، با امیدی که داستانش دیگران را الهام می‌بخشد به پایان رسید.")
                )
            ),
            StoryChapter(
                number = 6, title = "The End", titlePersian = "پایان",
                paragraphs = listOf(
                    StoryParagraph("And so the story of Lord Jim came to its final end, the story that Marlow had told so many times, the story that had become a part of him, the story that he would carry with him for the rest of his life.", "و اینگونه داستان لرد جیم به پایان نهایی‌اش رسید، داستانی که مارلو اینقدر بارها تعریف کرده بود، داستانی که بخشی از او شده بود، داستانی که باقی عمرش با خود حمل می‌کرد."),
                    StoryParagraph("For Marlow had learned something from Jim, had learned something about the nature of courage, had learned something about the nature of failure, had learned something about the nature of redemption.", "زیرا مارلو چیزی از جیم آموخته بود، چیزی درباره ماهیت شجاعت آموخته بود، چیزی درباره ماهیت شکست آموخته بود، چیزی درباره ماهیت رستگاری آموخته بود."),
                    StoryParagraph("He had learned that courage is not the absence of fear, but the willingness to act in spite of it, had learned that failure is not the end but the beginning, had learned that redemption is always possible, no matter how far one has fallen.", "او آموخته بود شجاعت نبود ترس نیست، بلکه آمادگی عمل کردن به رغم آن است، آموخته بود شکست پایان نیست بلکه آغاز است، آموخته بود رستگاری همیشه ممکن است، هر چقدر هم که کسی افتاده باشد."),
                    StoryParagraph("And Marlow had learned these things not from books, not from sermons, not from philosophers, but from the life and death of a young man named Jim, a man who had failed and who had risen again.", "و مارلو این چیزها را نه از کتاب‌ها آموخته بود، نه از موعظه‌ها، نه از فیلسوفان، بلکه از زندگی و مرگ جوانی به نام جیم، مردی که شکست خورده بود و دوباره برخاسته بود."),
                    StoryParagraph("For Jim had been a teacher, though he had not known it, had been a teacher by his example, had been a teacher by his failure, had been a teacher by his redemption, had been a teacher by his death.", "زیرا جیم معلمی بوده، هرچند نمی‌دانسته، معلمی به‌واسطه نمونه‌اش، معلمی به‌واسطه شکستش، معلمی به‌واسطه رستگاری‌اش، معلمی به‌واسطه مرگش."),
                    StoryParagraph("And Marlow, who had been his student, who had learned from him, who had been changed by him, felt a deep gratitude for the young man whose life had touched his own, whose story had become his own, whose lesson had become his own.", "و مارلو، که شاگردش بوده، که از او آموخته، که توسط او تغییر یافته، سپاس عمیقی برای آن جوان حس می‌کرد که زندگی‌اش زندگی‌اش را لمس کرده، داستانش داستانش شده، درسش درسش شده."),
                    StoryParagraph("For Jim had taught Marlow that we are all capable of failure, that we are all capable of courage, that we are all capable of redemption, and that what matters is not what we do but what we do next.", "زیرا جیم به مارلو آموخته بود که همه ما قادر به شکستیم، همه ما قادر به شجاعتیم، همه ما قادر به رستگاری‌ایم، و آنچه مهم است آنچه می‌کنیم نیست بلکه آنچه بعدش می‌کنیم است."),
                    StoryParagraph("And Marlow had learned that lesson, had taken it to heart, had made it a part of his own life, had allowed it to change the way he saw the world and the way he saw himself.", "و مارلو آن درس را آموخته بود، آن را به دل گرفته بود، آن را بخشی از زندگی خودش کرده بود، گذاشته بود شیوه دیدنش از جهان و شیوه دیدنش از خودش را تغییر دهد."),
                    StoryParagraph("For Marlow too had failed in his life, Marlow too had done things he regretted, Marlow too had carried the weight of his failures, and Marlow too had needed to learn that redemption was possible.", "زیرا مارلو هم در زندگی‌اش شکست خورده بود، مارلو هم کارهایی کرده بود که پشیمانشان بود، مارلو هم سنگینی شکست‌هایش را حمل کرده بود، و مارلو هم نیاز داشت بیاموزد که رستگاری ممکن است."),
                    StoryParagraph("And Jim had taught him that, had taught him through his life, had taught him through his death, had taught him through the story that Marlow would carry with him forever.", "و جیم این را به او آموخته بود، از طریق زندگی‌اش آموخته بود، از طریق مرگش آموخته بود، از طریق داستانی که مارلو برای همیشه با خود حمل می‌کرد آموخته بود."),
                    StoryParagraph("For stories are not merely entertainment, not merely ways to pass the time, but ways of knowing, ways of understanding, ways of growing, ways of becoming who we are meant to be.", "زیرا داستان‌ها تنها سرگرمی نیستند، تنها راه‌هایی برای گذراندن وقت نیستند، بلکه راه‌هایی برای دانستن، برای فهمیدن، برای رشد کردن، برای شدن آنکه باید باشیم هستند."),
                    StoryParagraph("And the story of Jim was one such story, a story that taught, a story that transformed, a story that redeemed, a story that would continue to teach and transform and redeem as long as it was told.", "و داستان جیم یکی از آن داستان‌ها بود، داستانی که آموزش می‌داد، داستانی که دگرگون می‌کرد، داستانی که رستگار می‌کرد، داستانی که به آموزش و دگرگون کردن و رستگار کردن ادامه می‌داد تا زمانی که تعریف می‌شد."),
                    StoryParagraph("And Marlow would continue to tell it, would tell it to all who would listen, would tell it in ports and in cities and in ships, would tell it until the end of his days.", "و مارلو به تعریفش ادامه می‌داد، برای همه کسانی که گوش می‌دادند تعریفش می‌کرد، در بندرها و شهرها و کشتی‌ها تعریفش می‌کرد، تا پایان روزهایش تعریفش می‌کرد."),
                    StoryParagraph("For in telling the story of Jim, Marlow was also telling the story of himself, was also telling the story of every human being who has ever failed, was also telling the story of every human being who has ever tried to rise above their failure.", "زیرا با تعریف داستان جیم، مارلو داستان خودش را هم تعریف می‌کرد، داستان هر انسانی که هرگز شکست خورده را هم تعریف می‌کرد، داستان هر انسانی که هرگز تلاش کرده از شکستش فراتر رود را هم تعریف می‌کرد."),
                    StoryParagraph("And so the story of Lord Jim came to an end, but the story of Jim was not really over, for stories never really end, they only pause, they only wait, they only bide their time until the next teller comes.", "و اینگونه داستان لرد جیم به پایان رسید، اما داستان جیم واقعاً تمام نشده بود، زیرا داستان‌ها هرگز واقعاً تمام نمی‌شوند، تنها مکث می‌کنند، تنها منتظر می‌مانند، تنها وقت‌کشی می‌کنند تا گوینده بعدی بیاید."),
                    StoryParagraph("And there would be a next teller, for there is always a next teller, for stories are passed from teller to teller, from generation to generation, from age to age, and they never lose their power to teach and to move.", "و گوینده بعدی می‌آمد، زیرا همیشه گوینده بعدی هست، زیرا داستان‌ها از گوینده به گوینده منتقل می‌شوند، از نسلی به نسل، از عصری به عصر، و هرگز قدرت آموزش و تأثیرشان را از دست نمی‌دهند."),
                    StoryParagraph("And so the story of Lord Jim would continue to be told, would continue to teach, would continue to transform, as long as there were human beings to hear it, as long as there were human beings to learn from it.", "و اینگونه داستان لرد جیم به تعریف شدن ادامه می‌داد، به آموزش دادن ادامه می‌داد، به دگرگون کردن ادامه می‌داد، تا زمانی که انسان‌هایی بودند که بشنوند، تا زمانی که انسان‌هایی بودند که از آن بیاموزند."),
                    StoryParagraph("For that is the power of stories, that they transcend the teller, that they transcend the time, that they transcend the place, that they speak to something eternal in the human heart.", "زیرا این قدرت داستان‌هاست، که از گوینده فراتر می‌روند، از زمان فراتر می‌روند، از مکان فراتر می‌روند، که به چیزی جاودان در قلب انسانی سخن می‌گویند."),
                    StoryParagraph("And the story of Jim, the story of a man who failed and who rose again, the story of a man who became a hero in spite of himself, the story of a man who found redemption in the most unexpected place, spoke to that eternal something.", "و داستان جیم، داستان مردی که شکست خورد و دوباره برخاست، داستان مردی که به رغم خودش قهرمان شد، داستان مردی که رستگاری را در غیرمنتظره‌ترین جا یافت، به آن چیز جاودان سخن می‌گفت."),
                    StoryParagraph("And so the story ended, and the darkness settled over the world, and the ships continued to sail, and the men continued to live and to fail and to rise again, and the story continued to be told.", "و اینگونه داستان تمام شد و تاریکی بر جهان نشست و کشتی‌ها به بادبانی ادامه دادند و مردان به زندگی و شکست خوردن و دوباره برخاستن ادامه دادند و داستان به تعریف شدن ادامه داد."),
                    StoryParagraph("For that is the meaning of Lord Jim, that we are all Jim, that we all fail, that we all have the chance to rise again, and that some of us, in the end, do.", "زیرا این معنای لرد جیم است، که همه ما جیم هستیم، که همه ما شکست می‌خوریم، که همه ما فرصت دوباره برخاستن را داریم، و برخی از ما، در پایان، این کار را می‌کنند."),
                    StoryParagraph("The end.", "پایان."),
                    StoryParagraph("But the story continues.", "اما داستان ادامه دارد."),
                    StoryParagraph("And so ended the sixth and final part of Jim's story, with the meaning of his life, with the hope of his death, with the certainty that his story would live on.", "و اینگونه بخش ششم و آخرین داستان جیم با معنای زندگی‌اش، با امید مرگش، با یقین به اینکه داستانش زنده می‌ماند به پایان رسید."),
                    StoryParagraph("For Jim had not died in vain, Jim had not failed in vain, Jim had not lived in vain, and his story, the story of Lord Jim, would continue to inspire all who heard it.", "زیرا جیم بیهوده نمرده بود، جیم بیهوده شکست نخورده بود، جیم بیهوده زندگی نکرده بود، و داستانش، داستان لرد جیم، به الهام بخشیدن به همه کسانی که می‌شنیدند ادامه می‌داد."),
                    StoryParagraph("And Marlow, wherever he was, would smile and remember, and would tell the story one more time, for the story was not Jim's alone, it was his own, it was everyone's, it was the story of us all.", "و مارلو، هر جا که بود، لبخند می‌زد و به یاد می‌آورد، و یک بار دیگر داستان را تعریف می‌کرد، زیرا داستان تنها مال جیم نبود، مال خودش بود، مال همه بود، داستان همه ما بود."),
                    StoryParagraph("And so the story of Lord Jim ended, as all stories must end, with a silence, a silence that was itself a meaning, a silence that was itself a peace.", "و اینگونه داستان لرد جیم به پایان رسید، همان‌طور که همه داستان‌ها باید تمام شوند، با سکوتی، سکوتی که خود معنایی بود، سکوتی که خود آرامشی بود.")
                )
            )
        )
    )

    // ═══════════════════════════════════════════════════════════
    // STORY 39 — Brave New World (Aldous Huxley)
    // ═══════════════════════════════════════════════════════════
    private fun story39() = StoryContent(
        storyId = "adv_brave_new_world",
        chapters = listOf(
            StoryChapter(
                number = 1, title = "The Hatchery", titlePersian = "مرکز پرورش",
                paragraphs = listOf(
                    StoryParagraph("A squat grey building of only thirty-four stories stood in the center of London, a building that bore the words over its main entrance: Central London Hatchery and Conditioning Centre, and above these words the World State's motto, Community, Identity, Stability.", "ساختمانی خاکستری و کوتاه تنها با سی و چهار طبقه در مرکز لندن ایستاده بود، ساختمانی که بالای ورودی اصلی‌اش نوشته بود: مرکز پرورش و شرطی‌سازی لندن مرکزی، و بالای این کلمات شعار دولت جهانی: جامعه، هویت، ثبات."),
                    StoryParagraph("It was a building dedicated to the production of human beings, a building that manufactured life as other buildings manufactured machines, a building that had perfected the art of creating people in test tubes and raising them in factories.", "ساختمانی بود وقف تولید انسان‌ها، ساختمانی که زندگی را تولید می‌کرد همان‌طور که ساختمان‌های دیگر ماشین تولید می‌کردند، ساختمانی که هنر آفریدن مردم در لوله‌های آزمایش و بزرگ کردنشان در کارخانه‌ها را کامل کرده بود."),
                    StoryParagraph("The Director of the Hatchery, a man named Thomas, led a group of students through the building, explaining to them the wonders of the process, showing them the marvels of scientific progress, revealing to them the secrets of a society that had achieved perfection.", "مدیر مرکز پرورش، مردی به نام توماس، گروهی از دانشجویان را در ساختمان راهنمایی می‌کرد، شگفتی‌های فرایند را برایشان توضیح می‌داد، معجزات پیشرفت علمی را نشانشان می‌داد، رازهای جامعه‌ای را که به کمال رسیده بود بر آنان آشکار می‌کرد."),
                    StoryParagraph("On the first floor, the Director explained, was the Fertilizing Room, where human eggs were fertilized and prepared for the process of incubation, a process that would produce not one child but dozens, not individuals but identical members of a caste.", "مدیر توضیح داد که در طبقه اول اتاق لقاح بود، جایی که تخمک‌های انسانی بارور و برای فرایند جوجه‌کشی آماده می‌شدند، فرایندی که نه یک کودک بلکه ده‌ها، نه افراد بلکه اعضای همسان یک کاست تولید می‌کرد."),
                    StoryParagraph("One egg, one embryo, one adult, normality, the Director said, but a bokanovskified egg will bud, will proliferate, will divide, from eight to ninety-six buds, and every bud will grow into a perfectly formed embryo, and every embryo into a full-sized adult.", "مدیر گفت: یک تخم، یک جنین، یک بزرگسال، طبیعی است، اما تخم بوکانوفسکی‌شده جوانه می‌زند، تکثیر می‌شود، تقسیم می‌شود، از هشت تا نود‌وشش جوانه، و هر جوانه به جنینی کاملاً شکل‌گرفته تبدیل می‌شود و هر جنین به بزرگسالی با اندازه کامل."),
                    StoryParagraph("Making ninety-six human beings grow where only one grew before, the Director said, progress, and the students wrote it down in their notebooks, for they had been taught that progress was the highest good, that progress was the purpose of civilization.", "مدیر گفت: ساختن نود‌وشش انسان در جایی که قبلاً تنها یکی رشد می‌کرد، پیشرفت، و دانشجویان آن را در دفترهایشان یادداشت کردند، زیرا به آنان آموخته بودند که پیشرفت عالی‌ترین خیر است، که پیشرفت هدف تمدن است."),
                    StoryParagraph("The Director explained the caste system, explained that human beings were now produced in five different grades, from Alpha to Epsilon, each grade designed for a different kind of work, each grade conditioned to be happy with its lot.", "مدیر نظام کاست را توضیح داد، توضیح داد که انسان‌ها اکنون در پنج درجه مختلف تولید می‌شوند، از آلفا تا اپسیلون، هر درجه برای نوع متفاوتی از کار طراحی شده، هر درجه شرطی شده تا با سرنوشتش خوشحال باشد."),
                    StoryParagraph("The Alphas, tall and beautiful, were destined for positions of leadership and intelligence, the Betas for less demanding intellectual work, the Gammas for skilled labor, the Deltas for unskilled labor, the Epsilons for the most menial tasks of all.", "آلفاها، بلندقد و زیبا، برای مقامات رهبری و هوش مقدر شده بودند، بتاها برای کارهای فکری کم‌طلبانه‌تر، گاماها برای کار ماهرانه، دلتاها برای کار غیرماهرانه، اپسیلون‌ها برای پست‌ترین کارها از همه."),
                    StoryParagraph("Each caste was conditioned from before birth to love its destiny, to desire nothing more, to envy no one, to accept the world as it was and to be happy in it, and this conditioning was the true genius of the World State.", "هر کاست از پیش از تولد شرطی شده بود که سرنوشتش را دوست بدارد، چیزی بیشتر نخواهد، به کسی حسادت نکند، جهان را همان‌طور که بود بپذیرد و در آن خوشحال باشد، و این شرطی‌سازی نابغه واقعی دولت جهانی بود."),
                    StoryParagraph("The Director led the students to the Nurseries, where babies were being trained to love their caste, where babies were being taught to hate the things their caste was not supposed to do, where babies were being conditioned to be perfect citizens.", "مدیر دانشجویان را به پرورشگاه‌ها برد، جایی که نوزادان آموزش می‌دیدند کاستشان را دوست بدارند، جایی که نوزادان یاد می‌گرفتند از چیزهایی که کاستشان نباید بکند متنفر باشند، جایی که نوزادان شرطی می‌شدند تا شهروندان کامل باشند."),
                    StoryParagraph("He showed them the Neo-Pavlovian Conditioning Rooms, where babies were given electric shocks when they reached for books and flowers, where babies were taught to hate nature and to love machines, where babies were programmed for the tasks they would perform as adults.", "او اتاق‌های شرطی‌سازی نئو-پاولفی را نشانشان داد، جایی که نوزادان وقتی به سمت کتاب‌ها و گل‌ها دست می‌بردند شوک الکتریکی می‌گرفتند، جایی که نوزادان یاد می‌گرفتند از طبیعت متنفر و ماشین‌ها را دوست بدارند، جایی که نوزادان برای وظایفی که به‌عنوان بزرگسال انجام می‌دادند برنامه‌ریزی می‌شدند."),
                    StoryParagraph("The Director explained the importance of these methods, explained that a love of nature was a waste of time, that a love of books was a danger to society, that a love of anything other than consumption and pleasure was a threat to stability.", "مدیر اهمیت این روش‌ها را توضیح داد، توضیح داد که عشق به طبیعت اتلاف وقت است، که عشق به کتاب‌ها خطری برای جامعه است، که عشق به هر چیزی جز مصرف و لذت تهدیدی برای ثبات است."),
                    StoryParagraph("We also predestine and condition, the Director said, we decant our babies as socialized human beings, as Alphas or Epsilons, as future sewage workers or future directors of hatcheries, and we condition them to love their fate.", "مدیر گفت: ما نیز تقدیر و شرطی می‌کنیم، ما نوزادانمان را به‌عنوان انسان‌های اجتماعی‌شده به دنیا می‌آوریم، به‌عنوان آلفا یا اپسیلون، به‌عنوان کارگران فاضلاب آینده یا مدیران مراکز پرورش آینده، و آنان را شرطی می‌کنیم که سرنوشتشان را دوست بدارند."),
                    StoryParagraph("The students listened, the students took notes, the students marveled at the wonders of this new world, for they had been raised in this world and had never known any other, had never questioned any of its assumptions, had never imagined that things could be different.", "دانشجویان گوش دادند، دانشجویان یادداشت برداشتند، دانشجویان از شگفتی‌های این جهان نو حیرت کردند، زیرا در این جهان بزرگ شده بودند و هیچ جهان دیگری را نمی‌شناختند، هرگز هیچ‌کدام از فرض‌هایش را زیر سؤال نبرده بودند، هرگز تصور نکرده بودند که چیزها می‌توانند متفاوت باشند."),
                    StoryParagraph("And this, the Director said, is the secret of happiness and virtue, liking what you've got to do, all conditioning aims at that, making people like their inescapable social destiny.", "و مدیر گفت: این راز خوشبختی و فضیلت است، دوست داشتن آنچه باید بکنی، تمام شرطی‌سازی هدفش همین است، وادار کردن مردم به دوست داشتن سرنوشت اجتماعی ناگزیرشان."),
                    StoryParagraph("The Director spoke of the past, of the time before the World State, when human beings were born from mothers, when families existed, when people grew old and died, when there was suffering and poverty and war, when there was no stability.", "مدیر از گذشته گفت، از زمان پیش از دولت جهانی، وقتی انسان‌ها از مادران زاده می‌شدند، وقتی خانواده‌ها وجود داشتند، وقتی مردم پیر می‌شدند و می‌مردند، وقتی رنج و فقر و جنگ بود، وقتی ثباتی نبود."),
                    StoryParagraph("Those were dark times, the Director said, times of chaos and misery, times when human beings were not conditioned, times when they were free to suffer, free to fail, free to make mistakes, times that we have thankfully left behind.", "مدیر گفت: آن زمان‌های تاریکی بود، زمان‌های آشوب و بدبختی، زمان‌هایی که انسان‌ها شرطی نشده بودند، زمان‌هایی که آزاد بودند رنج بکشند، آزاد بودند شکست بخورند، آزاد بودند اشتباه کنند، زمان‌هایی که خوشبختانه پشت سر گذاشته‌ایم."),
                    StoryParagraph("The Director showed them the records, showed them the statistics, showed them the evidence that the old world had been a nightmare of suffering, that the new world was a paradise of happiness, that the World State had saved humanity from itself.", "مدیر سوابق را نشانشان داد، آمار را نشانشان داد، شواهدی را نشانشان داد که جهان کهن کابوسی از رنج بوده، که جهان نو بهشتی از خوشبختی است، که دولت جهانی بشریت را از خودش نجات داده است."),
                    StoryParagraph("And the students believed him, believed everything he said, for they had been conditioned to believe, had been conditioned to accept, had been conditioned to be happy with the world as it was, and they did not know that they had been conditioned.", "و دانشجویان باورش کردند، هر چه گفت باورش کردند، زیرا شرطی شده بودند که باور کنند، شرطی شده بودند که بپذیرند، شرطی شده بودند که با جهان همان‌طور که بود خوشحال باشند، و نمی‌دانستند که شرطی شده‌اند."),
                    StoryParagraph("And this, perhaps, was the true genius of the World State, not that it had enslaved humanity, but that it had made humanity love its slavery, not that it had destroyed freedom, but that it had made humanity forget that freedom had ever existed.", "و این، شاید، نابغه واقعی دولت جهانی بود، نه اینکه بشریت را به بردگی گرفته بود، بلکه اینکه بشریت را وادار کرده بود بردگی‌اش را دوست بدارد، نه اینکه آزادی را نابود کرده بود، بلکه اینکه بشریت را وادار کرده بود فراموش کند آزادی هرگز وجود داشته."),
                    StoryParagraph("The Director finished the tour and the students left, carrying with them the lessons they had learned, the lessons that would make them good citizens, the lessons that would make them happy, the lessons that would make them obedient.", "مدیر تور را تمام کرد و دانشجویان رفتند، با خود درس‌هایی که آموخته بودند حمل می‌کردند، درس‌هایی که آنان را شهروندان خوبی می‌کرد، درس‌هایی که آنان را خوشحال می‌کرد، درس‌هایی که آنان را فرمانبردار می‌کرد."),
                    StoryParagraph("And so ended the first part of the story of the Brave New World, with a tour of the Hatchery, with a lesson in conditioning, with the revelation of a world that had achieved stability at the cost of everything else.", "و اینگونه بخش نخست داستان دنیای قشنگ نو با توری در مرکز پرورش، با درسی در شرطی‌سازی، با مکاشفه جهانی که ثبات را به قیمت هر چیز دیگری به دست آورده بود به پایان رسید.")
                )
            ),
            StoryChapter(
                number = 2, title = "Bernard Marx", titlePersian = "برنارد مارکس",
                paragraphs = listOf(
                    StoryParagraph("Bernard Marx was an Alpha Plus, a member of the highest caste, a man who should have been happy, who should have been fulfilled, who should have been content with his privileged position in the World State.", "برنارد مارکس آلفا پلاس بود، عضوی از بالاترین کاست، مردی که باید خوشحال می‌بود، باید کامل می‌بود، باید با جایگاه ممتازش در دولت جهانی قانع می‌بود."),
                    StoryParagraph("But Bernard was not happy, Bernard was not fulfilled, Bernard was not content, for Bernard was different, Bernard was smaller than the other Alphas, Bernard had been given a reputation for being strange, and Bernard knew it.", "اما برنارد خوشحال نبود، برنارد کامل نبود، برنارد قانع نبود، زیرا برنارد متفاوت بود، برنارد کوچک‌تر از آلفاهای دیگر بود، برنارد آوازه عجیب بودن گرفته بود، و برنارد می‌دانست."),
                    StoryParagraph("It was said that someone had blundered at the time of his decanting, that alcohol had been poured into his blood surrogate, and the result was a man who was physically inferior, who was psychologically unstable, who was a misfit in a world of perfect people.", "می‌گفتند کسی در زمان به دنیا آوردنش اشتباه کرده بود، الکل در جانشین خونش ریخته شده بود، و نتیجه مردی بود که از نظر جسمی پست‌تر بود، از نظر روانی ناپایدار بود، در جهانی از افراد کامل نامناسب بود."),
                    StoryParagraph("Bernard knew that he was different, and he hated himself for it, and he hated the world for making him hate himself, and he hated the people who looked at him with pity and with contempt, and he hated everything.", "برنارد می‌دانست که متفاوت است و از این بابت از خودش متنفر بود و از جهانی که او را وادار به نفرت از خودش کرده بود متنفر بود و از مردمی که با ترحم و تحقیر به او نگاه می‌کردند متنفر بود و از همه چیز متنفر بود."),
                    StoryParagraph("He was lonely, desperately lonely, in a world where loneliness was supposed to be impossible, in a world where everyone was supposed to be happy, in a world where everyone was supposed to belong.", "او تنها بود، به‌شدت تنها، در جهانی که تنهایی قرار بود ناممکن باشد، در جهانی که همه قرار بود خوشحال باشند، در جهانی که همه قرار بود تعلق داشته باشند."),
                    StoryParagraph("Bernard sought comfort in the things that the World State offered, sought comfort in sex and in drugs, sought comfort in the endless distractions of a society designed to prevent thought, sought comfort in everything that was supposed to make him happy.", "برنارد در چیزهایی که دولت جهانی پیشنهاد می‌داد تسلی می‌جست، در سکس و در دارو تسلی می‌جست، در سرگرمی‌های بی‌پایان جامعه‌ای که برای جلوگیری از فکر کردن طراحی شده بود تسلی می‌جست، در هر چیزی که قرار بود خوشحالش کند تسلی می‌جست."),
                    StoryParagraph("But nothing worked, for Bernard's problem was not in his circumstances but in himself, his problem was not that he lacked pleasure but that he wanted something more, something that the World State could not provide.", "اما هیچ چیز کار نکرد، زیرا مشکل برنارد در شرایطش نبود بلکه در خودش بود، مشکلش این نبود که لذت نداشت بلکه می‌خواست چیزی بیشتر، چیزی که دولت جهانی نمی‌توانست فراهم کند."),
                    StoryParagraph("Bernard wanted to be an individual, wanted to be himself, wanted to be more than just a member of a caste, wanted to be more than just a cog in a machine, wanted to be more than just a happy slave.", "برنارد می‌خواست فرد باشد، می‌خواست خودش باشد، می‌خواست بیشتر از تنها عضوی از یک کاست باشد، می‌خواست بیشتر از تنها چرخی در ماشین باشد، می‌خواست بیشتر از تنها برده‌ای خوشحال باشد."),
                    StoryParagraph("But he did not know how to be these things, did not know how to be an individual in a world that had abolished individuality, did not know how to be himself in a world that had abolished the self.", "اما نمی‌دانست چطور این چیزها باشد، نمی‌دانست چطور در جهانی که فردیت را لغو کرده بود فرد باشد، نمی‌دانست چطور در جهانی که خود را لغو کرده بود خودش باشد."),
                    StoryParagraph("Bernard had a friend, a man named Helmholtz Watson, an Alpha who was also different, an Alpha who was also dissatisfied, an Alpha who also wanted something more than the World State could provide.", "برنارد دوستی داشت، مردی به نام هلمولتز واتسون، آلفایی که او هم متفاوت بود، آلفایی که او هم ناراضی بود، آلفایی که او هم چیزی بیشتر از آنچه دولت جهانی می‌توانست فراهم کند می‌خواست."),
                    StoryParagraph("Helmholtz was a writer, a man who produced the feelies and the hypnopaedic slogans that kept the World State running, a man who was celebrated for his work, a man who should have been happy, a man who was not.", "هلمولتز نویسنده بود، مردی که فیلم‌های حسی و شعارهای خواب‌آموز که دولت جهانی را سرپا نگه می‌داشت تولید می‌کرد، مردی که برای کارش مشهور بود، مردی که باید خوشحال می‌بود، مردی که نبود."),
                    StoryParagraph("Helmholtz had a gift, a gift for words, a gift for making people feel things, but he did not want to make people feel the things the World State wanted them to feel, he wanted to make them feel something real.", "هلمولتز استعدادی داشت، استعدادی برای کلمات، استعدادی برای وادار کردن مردم به حس کردن چیزها، اما نمی‌خواست مردم چیزهایی را حس کنند که دولت جهانی می‌خواست، می‌خواست آنان چیزی واقعی حس کنند."),
                    StoryParagraph("But he did not know what real meant, had never experienced anything real, had lived his whole life in a world of manufactured pleasures and conditioned responses, and he did not know if there was anything else.", "اما نمی‌دانست واقعی یعنی چه، هرگز چیزی واقعی تجربه نکرده بود، تمام عمرش در جهانی از لذت‌های ساختگی و پاسخ‌های شرطی زندگی کرده بود، و نمی‌دانست آیا چیز دیگری هم هست."),
                    StoryParagraph("Bernard and Helmholtz talked, shared their dissatisfaction, shared their loneliness, shared their longing for something they could not name, and in their sharing they found a moment of connection, a moment of something that felt real.", "برنارد و هلمولتز صحبت کردند، نارضایتی‌شان را قسمت کردند، تنهایی‌شان را قسمت کردند، اشتیاقشان به چیزی که نمی‌توانستند نامش را ببرند قسمت کردند، و در قسمت کردنشان لحظه‌ای از ارتباط یافتند، لحظه‌ای از چیزی که واقعی به نظر می‌رسید."),
                    StoryParagraph("And so ended the second part of the story of the Brave New World, with the introduction of the two men who would change everything, the two men who would question the world they lived in, the two men who would discover that there was another way.", "و اینگونه بخش دوم داستان دنیای قشنگ نو با معرفی دو مردی به پایان رسید که همه چیز را تغییر می‌دادند، دو مردی که جهانی که در آن زندگی می‌کردند را زیر سؤال می‌بردند، دو مردی که کشف می‌کردند راه دیگری هم هست.")
                )
            ),
            StoryChapter(
                number = 3, title = "Lenina Crowne", titlePersian = "لنینا کراون",
                paragraphs = listOf(
                    StoryParagraph("Lenina Crowne was a beautiful Beta, a woman who worked in the Hatchery, a woman who was admired by all who knew her, a woman who was supposed to be perfectly happy in the perfectly ordered world of the World State.", "لنینا کراون بتای زیبایی بود، زنی که در مرکز پرورش کار می‌کرد، زنی که همه کسانی که می‌شناختندش تحسینش می‌کردند، زنی که قرار بود در جهان به‌طور کامل مرتب دولت جهانی به‌طور کامل خوشحال باشد."),
                    StoryParagraph("Lenina was popular, Lenina was desired, Lenina was never alone, for in the World State no one was ever alone, and to be alone was considered a sign of abnormality, a sign of illness, a sign that something was wrong.", "لنینا محبوب بود، لنینا مورد میل بود، لنینا هرگز تنها نبود، زیرا در دولت جهانی هیچ‌کس هرگز تنها نبود، و تنها بودن نشانه‌ای از ناهنجاری بود، نشانه‌ای از بیماری، نشانه‌ای که چیزی اشتباه است."),
                    StoryParagraph("But Lenina was not happy, or rather she was happy in the way that she was supposed to be happy, which is not the same as being happy, and she did not know the difference, for she had been conditioned not to know it.", "اما لنینا خوشحال نبود، یا بهتر، به شیوه‌ای خوشحال بود که قرار بود خوشحال باشد، که همان خوشحال بودن نیست، و تفاوت را نمی‌دانست، زیرا شرطی شده بود که نداند."),
                    StoryParagraph("Lenina was tired of the endless round of pleasure, tired of the endless sex, tired of the endless soma, tired of the endless distractions, tired of the endless everything that was supposed to make her happy.", "لنینا از چرخه بی‌پایان لذت خسته بود، از سکس بی‌پایان خسته بود، از سوما بی‌پایان خسته بود، از سرگرمی‌های بی‌پایان خسته بود، از همه چیز بی‌پایانی که قرار بود خوشحالش کند خسته بود."),
                    StoryParagraph("She wanted something different, something more, something real, but she did not know what, and she did not know how to find it, and she did not know if it existed.", "چیزی متفاوت می‌خواست، چیزی بیشتر، چیزی واقعی، اما نمی‌دانست چه، و نمی‌دانست چطور پیدایش کند، و نمی‌دانست وجود دارد یا نه."),
                    StoryParagraph("Lenina met Bernard Marx, was introduced by a mutual friend, and something about him interested her, something about his difference, something about his loneliness, something about his pain, attracted her.", "لنینا برنارد مارکس را ملاقات کرد، توسط دوستی مشترک معرفی شد، و چیزی درباره او علاقه‌مندش کرد، چیزی درباره تفاوتش، چیزی درباره تنهایی‌اش، چیزی درباره دردی‌اش، جذبش کرد."),
                    StoryParagraph("Bernard was not like the other men, Bernard did not try to possess her, Bernard did not treat her as an object, Bernard talked to her as if she were a person, and Lenina found this strange and fascinating.", "برنارد مثل مردان دیگر نبود، برنارد تلاش نمی‌کرد مالکش شود، برنارد با او مثل شیء رفتار نمی‌کرد، برنارد با او طوری صحبت می‌کرد که گویی انسان است، و لنینا این را عجیب و جذاب یافت."),
                    StoryParagraph("Bernard invited Lenina to go with him to the Savage Reservation, to see the place where the old world still existed, to see the people who had not been conditioned, to see something that was real.", "برنارد لنینا را دعوت کرد با او به منطقه وحشی برود، جایی که جهان کهن هنوز وجود داشت را ببیند، مردمی که شرطی نشده بودند را ببیند، چیزی واقعی ببیند."),
                    StoryParagraph("Lenina was curious, Lenina wanted to see the place, Lenina wanted to see the savages, Lenina wanted to see what life had been like before the World State, and Lenina agreed to go.", "لنینا کنجکاو بود، لنینا می‌خواست جا را ببیند، لنینا می‌خواست وحشی‌ها را ببیند، لنینا می‌خواست ببیند زندگی پیش از دولت جهانی چه شکلی بوده، و لنینا موافقت کرد برود."),
                    StoryParagraph("They traveled to the Reservation, they saw the savages, they saw people who were old and sick and suffering, they saw people who had families and who knew love and who knew grief, they saw people who were human.", "آن‌ها به منطقه وحشی سفر کردند، وحشی‌ها را دیدند، مردمی را دیدند که پیر و بیمار و رنجور بودند، مردمی را دیدند که خانواده داشتند و عشق می‌شناختند و اندوه می‌شناختند، مردمی را دیدند که انسان بودند."),
                    StoryParagraph("And Lenina was horrified, for she had been conditioned to see such things as disgusting, as primitive, as wrong, and she was unable to see them for what they were.", "و لنینا وحشت کرد، زیرا شرطی شده بود چنین چیزهایی را چندش‌آور ببیند، ابتدایی، غلط، و قادر نبود آن‌ها را آن‌گونه که بودند ببیند."),
                    StoryParagraph("Bernard was fascinated, for he had been longing for something real, and here was something real, and he wanted to understand it, and he wanted to become part of it.", "برنارد شیفته شد، زیرا در آرزوی چیزی واقعی بود و اینجا چیزی واقعی بود و می‌خواست بفهمدش و می‌خواست بخشی از آن شود."),
                    StoryParagraph("And in the Reservation, they found a man named John, a young man with blond hair and blue eyes, a young man who had been born in the Reservation, a young man who was the son of a woman from the World State.", "و در منطقه وحشی، مردی به نام جان یافتند، جوانی با موهای بلوند و چشمان آبی، جوانی که در منطقه وحشی زاده شده بود، جوانی که پسر زنی از دولت جهانی بود."),
                    StoryParagraph("John was a savage, but he was also a reader, had read Shakespeare, had learned about the world beyond the Reservation, had dreamed of visiting that world, had imagined that it would be a paradise, had imagined that it would be the Brave New World.", "جان وحشی بود، اما خواننده هم بود، شکسپیر خوانده بود، درباره جهانی فراتر از منطقه وحشی آموخته بود، آرزوی بازدید از آن جهان را داشت، تصور کرده بود بهشتی است، تصور کرده بود دنیای قشنگ نو است."),
                    StoryParagraph("And so ended the third part of the story of the Brave New World, with the meeting of Bernard and Lenina with John, with the introduction of the man who would see the World State with fresh eyes, the man who would challenge everything it stood for.", "و اینگونه بخش سوم داستان دنیای قشنگ نو با ملاقات برنارد و لنینا با جان، با معرفی مردی به پایان رسید که دولت جهانی را با چشمانی تازه می‌دید، مردی که همه چیزی که نمایندگی می‌کرد را به چالش می‌کشید.")
                )
            ),
            StoryChapter(
                number = 4, title = "The Savage", titlePersian = "وحشی",
                paragraphs = listOf(
                    StoryParagraph("John came to London, came to the World State, came to the civilization that he had dreamed of, and what he found was not a paradise but a nightmare, not a utopia but a dystopia, not a brave new world but a brave new hell.", "جان به لندن آمد، به دولت جهانی آمد، به تمدنی آمد که در خواب دیده بود، و آنچه یافت بهشت نبود بلکه کابوس بود، آرمان‌شهر نبود بلکه نا‌آرمان‌شهر بود، دنیای قشنگ نو نبود بلکه دوزخ قشنگ نو بود."),
                    StoryParagraph("John was brought to London by Bernard, who wanted to use him as a weapon against the Director, who wanted to use him to gain power and prestige, who wanted to use him for his own purposes, and John did not understand this at first.", "جان توسط برنارد به لندن آورده شد، که می‌خواست از او به‌عنوان سلاحی علیه مدیر استفاده کند، که می‌خواست از او برای کسب قدرت و آبرو استفاده کند، که می‌خواست از او برای اهداف خودش استفاده کند، و جان اولش این را نفهمید."),
                    StoryParagraph("John was celebrated, was paraded, was shown off, was treated as a curiosity, was treated as a savage, was treated as something less than human, and John began to understand what the World State really was.", "جان جشن گرفته شد، به نمایش گذاشته شد، به رخ کشیده شد، به‌عنوان کنجکاوی رفتار شد، به‌عنوان وحشی رفتار شد، به‌عنوان چیزی کمتر از انسان رفتار شد، و جان شروع کرد به فهمیدن دولت جهانی واقعاً چیست."),
                    StoryParagraph("He saw the conditioning, saw the castes, saw the people who had been made to love their slavery, saw the people who had been made to forget that they were slaves, saw the people who had been made to be happy with their chains.", "او شرطی‌سازی را دید، کاست‌ها را دید، مردمی را دید که وادار شده بودند بردگی‌شان را دوست بدارند، مردمی را دید که وادار شده بودند فراموش کنند که برده‌اند، مردمی را دید که وادار شده بودند با زنجیرهایشان خوشحال باشند."),
                    StoryParagraph("He saw the soma, saw the drug that made people forget, saw the drug that made people happy, saw the drug that made people obedient, saw the drug that was the true ruler of the World State.", "او سوما را دید، دارویی را دید که مردم را وادار به فراموش کردن می‌کرد، دارویی را دید که مردم را خوشحال می‌کرد، دارویی را دید که مردم را فرمانبردار می‌کرد، دارویی را دید که حاکم واقعی دولت جهانی بود."),
                    StoryParagraph("He saw the promiscuity, saw the endless sex, saw the people who had been conditioned to never form deep connections, saw the people who had been conditioned to never love, saw the people who had been conditioned to never be truly human.", "او بی‌بند و باری را دید، سکس بی‌پایان را دید، مردمی را دید که شرطی شده بودند هرگز ارتباطات عمیق شکل ندهند، مردمی را دید که شرطی شده بودند هرگز عشق نورزند، مردمی را دید که شرطی شده بودند هرگز به‌راستی انسان نباشند."),
                    StoryParagraph("He saw the death conditioning, saw the children who were taught not to fear death, saw the children who were taught to see death as normal, saw the children who were taught that life was not sacred.", "او شرطی‌سازی مرگ را دید، کودکانی را دید که یاد می‌گرفتند از مرگ نترسند، کودکانی را دید که یاد می‌گرفتند مرگ را طبیعی ببینند، کودکانی را دید که یاد می‌گرفتند زندگی مقدس نیست."),
                    StoryParagraph("And John was horrified, was disgusted, was outraged, was filled with a rage that he could not contain, and he began to speak, to speak of freedom, to speak of truth, to speak of beauty, to speak of everything that the World State had destroyed.", "و جان وحشت کرد، چندشش شد، خشمگین شد، پر از خشمی شد که نمی‌توانست در خود نگه دارد، و شروع کرد به سخن گفتن، از آزادی گفتن، از حقیقت گفتن، از زیبایی گفتن، از هر چیزی که دولت جهانی نابود کرده بود گفتن."),
                    StoryParagraph("But no one listened, no one understood, no one cared, for the people of the World State had been conditioned not to listen, not to understand, not to care, and John was alone in his outrage.", "اما هیچ‌کس گوش نداد، هیچ‌کس نفهمید، هیچ‌کس اهمیت نداد، زیرا مردم دولت جهانی شرطی شده بودند که گوش ندهند، نفهمند، اهمیت ندهند، و جان در خشمش تنها بود."),
                    StoryParagraph("He met Helmholtz, who understood, who had been waiting for someone like John, who had been waiting for something real, who had been waiting for a reason to believe that there was more to life than the World State allowed.", "او هلمولتز را ملاقات کرد، که فهمید، که منتظر کسی مثل جان بوده، که منتظر چیزی واقعی بوده، که منتظر دلیلی برای باور به اینکه زندگی بیشتر از آنچه دولت جهانی اجازه می‌داد هست بوده."),
                    StoryParagraph("They talked, talked of Shakespeare, talked of poetry, talked of beauty, talked of truth, and for the first time in their lives, both of them felt that they were speaking to someone who truly understood.", "آن‌ها صحبت کردند، از شکسپیر صحبت کردند، از شعر صحبت کردند، از زیبایی صحبت کردند، از حقیقت صحبت کردند، و برای اولین بار در زندگی‌شان، هر دو حس کردند با کسی صحبت می‌کنند که به‌راستی می‌فهمد."),
                    StoryParagraph("But the World State did not tolerate such connections, the World State did not tolerate such ideas, the World State did not tolerate such threats to its stability, and it acted, as it always acted, to eliminate the threat.", "اما دولت جهانی چنین ارتباطاتی را تحمل نمی‌کرد، دولت جهانی چنین ایده‌هایی را تحمل نمی‌کرد، دولت جهانی چنین تهدیدهایی برای ثباتش را تحمل نمی‌کرد، و عمل کرد، همان‌طور که همیشه عمل می‌کرد، برای حذف تهدید."),
                    StoryParagraph("Helmholtz was arrested, was sent away, was exiled to a distant island, and John was left alone, more alone than he had ever been, more alone than he had ever imagined possible, more alone than any human being should ever have to be.", "هلمولتز دستگیر شد، تبعید شد، به جزیره‌ای دور تبعید شد، و جان تنها ماند، تنهاتر از آنچه تا به حال بوده، تنهاتر از آنچه تصور می‌کرد ممکن است، تنهاتر از آنچه هر انسانی باید مجبور باشد باشد."),
                    StoryParagraph("John withdrew from the World State, went to live in a lighthouse, went to live in solitude, went to live in a place where he could be himself, where he could pray, where he could fast, where he could suffer, where he could be human.", "جان از دولت جهانی عقب‌نشینی کرد، رفت در فانوسی زندگی کند، در انزوا زندگی کند، در جایی زندگی کند که می‌توانست خودش باشد، جایی که می‌توانست دعا کند، جایی که می‌توانست روزه بگیرد، جایی که می‌توانست رنج بکشد، جایی که می‌توانست انسان باشد."),
                    StoryParagraph("But the World State would not leave him alone, the World State would not allow him his solitude, the World State would not tolerate anyone who refused to be part of its system, and soon they came, the reporters, the filmmakers, the curious, the masses.", "اما دولت جهانی او را تنها نمی‌گذاشت، دولت جهانی به او اجازه انزوایش را نمی‌داد، دولت جهانی هیچ‌کس که امتناع می‌کرد بخشی از نظامش باشد را تحمل نمی‌کرد، و به‌زودی آمدند، خبرنگاران، فیلمسازان، کنجکاوان، توده‌ها."),
                    StoryParagraph("They came to see the savage, they came to mock the savage, they came to exploit the savage, they came to destroy the savage, and John, in his despair, lashed out, and in his lashing out, he destroyed the only thing he had left: his own life.", "آمدند تا وحشی را ببینند، آمدند تا وحشی را مسخره کنند، آمدند تا وحشی را استثمار کنند، آمدند تا وحشی را نابود کنند، و جان، در ناامیدی‌اش، حمله کرد، و در حمله‌اش، تنها چیزی که برایش مانده بود را نابود کرد: جان خودش را."),
                    StoryParagraph("And so ended the fourth part of the story of the Brave New World, with the destruction of the only man who dared to be free, with the death of the only man who dared to be human, with the final proof that the World State had achieved its goal.", "و اینگونه بخش چهارم داستان دنیای قشنگ نو با نابودی تنها مردی که جرات آزاد بودن داشت، با مرگ تنها مردی که جرات انسان بودن داشت، با اثبات نهایی که دولت جهانی به هدفش رسیده بود به پایان رسید.")
                )
            ),
            StoryChapter(
                number = 5, title = "The End of Bernard", titlePersian = "پایان برنارد",
                paragraphs = listOf(
                    StoryParagraph("Bernard Marx had thought that bringing John to London would make him a hero, would make him powerful, would make him respected, would make him everything he had ever wanted to be, but he had been wrong.", "برنارد مارکس فکر کرده بود آوردن جان به لندن او را قهرمان می‌کند، قدرتمندش می‌کند، محترمش می‌کند، هر چیزی که همیشه می‌خواست باشد می‌کند، اما اشتباه کرده بود."),
                    StoryParagraph("Bernard had been celebrated for a time, had been fêted, had been admired, had been the center of attention, but the attention had turned to John, and Bernard had been forgotten, had been cast aside, had been returned to his former status as a misfit.", "برنارد مدتی جشن گرفته شده بود، پذیرایی شده بود، تحسین شده بود، مرکز توجه بوده، اما توجه به جان چرخیده بود، و برنارد فراموش شده بود، کنار گذاشته شده بود، به وضعیت سابقش به‌عنوان یک نامناسب بازگردانده شده بود."),
                    StoryParagraph("Bernard was bitter, was angry, was resentful, was jealous, and he took his bitterness out on John, blamed John for his fall, accused John of ingratitude, and in his jealousy he destroyed the only real friendship he had ever had.", "برنارد تلخ بود، عصبانی بود، دلخور بود، حسود بود، و تلخی‌اش را بر جان خالی کرد، جان را برای سقوطش سرزنش کرد، جان را به ناسپاسی متهم کرد، و در حسادتش تنها دوستی واقعی که تا به حال داشته بود را نابود کرد."),
                    StoryParagraph("Helmholtz tried to help Bernard, tried to make him see the truth, tried to make him understand that he had brought his suffering on himself, but Bernard would not listen, could not listen, for he was too wrapped up in his own pain.", "هلمولتز تلاش کرد به برنارد کمک کند، تلاش کرد او را وادار کند حقیقت را ببیند، تلاش کرد او را وادار کند بفهمد رنجش را خودش بر خودش آورده بود، اما برنارد گوش نمی‌داد، نمی‌توانست گوش دهد، زیرا بیش از حد در درد خودش غرق بود."),
                    StoryParagraph("And so, when Helmholtz was arrested, when Helmholtz was exiled, Bernard was left alone, more alone than he had ever been, more alone than he had ever imagined possible, and in his loneliness he finally understood what he had lost.", "و اینگونه، وقتی هلمولتز دستگیر شد، وقتی هلمولتز تبعید شد، برنارد تنها ماند، تنهاتر از آنچه تا به حال بوده، تنهاتر از آنچه تصور می‌کرد ممکن است، و در تنهایی‌اش سرانجام فهمید چه از دست داده."),
                    StoryParagraph("He had lost Helmholtz, lost the only person who had ever truly understood him, lost the only person who had ever truly been his friend, lost the only person who had ever truly cared whether he lived or died.", "هلمولتز را از دست داده بود، تنها کسی که هرگز به‌راستی درکش کرده بود را از دست داده بود، تنها کسی که هرگز به‌راستی دوستش بوده را از دست داده بود، تنها کسی که هرگز به‌راستی اهمیت داده بود زنده می‌ماند یا می‌میرد را از دست داده بود."),
                    StoryParagraph("Bernard was invited to join Helmholtz in his exile, but he refused, was too afraid, was too attached to the comforts of the World State, was too unwilling to give up the soma and the sex and the endless distractions.", "برنارد دعوت شد به هلمولتز در تبعیدش بپیوندد، اما امتناع کرد، بیش از حد ترسیده بود، بیش از حد به راحتی‌های دولت جهانی وابسته بود، بیش از حد بی‌میل بود که سومای و سکس و سرگرمی‌های بی‌پایان را رها کند."),
                    StoryParagraph("And so Bernard stayed, stayed in the World State, stayed in the world that had rejected him, stayed in the world that had made him what he was, and he tried to find happiness, tried to find comfort, tried to find peace.", "و اینگونه برنارد ماند، در دولت جهانی ماند، در جهانی که ردش کرده بود ماند، در جهانی که او را آنچه بود ساخته بود ماند، و تلاش کرد خوشبختی بیابد، تلاش کرد تسلی بیابد، تلاش کرد آرامش بیابد."),
                    StoryParagraph("But happiness did not come, comfort did not come, peace did not come, for Bernard had seen the truth, had seen what the World State really was, had seen what he himself really was, and he could not unsee it.", "اما خوشبختی نیامد، تسلی نیامد، آرامش نیامد، زیرا برنارد حقیقت را دیده بود، دیده بود دولت جهانی واقعاً چیست، دیده بود خودش واقعاً چیست، و نمی‌توانست نبینی‌اش."),
                    StoryParagraph("He had seen that the World State was built on lies, that its happiness was a sham, that its stability was a prison, that its perfection was a death, and he could not go back to believing the lies he had once believed.", "او دیده بود که دولت جهانی بر دروغ‌ها بنا شده، که خوشبختی‌اش تقلبی است، که ثباتش زندانی است، که کمالش مرگی است، و نمی‌توانست به باور دروغ‌هایی که روزی باور داشت بازگردد."),
                    StoryParagraph("Bernard lived the rest of his life in this state, this state of knowing and not being able to act, this state of seeing and not being able to change, this state of being awake in a world of sleepers.", "برنارد باقی عمرش را در این حالت زندگی کرد، این حالت دانستن و نتوانستن عمل کردن، این حالت دیدن و نتوانستن تغییر دادن، این حالت بیدار بودن در جهانی از خواب‌رفتگان."),
                    StoryParagraph("And sometimes, in his darkest moments, he wished he had never met John, wished he had never learned the truth, wished he had remained in his comfortable ignorance, wished he had remained a happy slave.", "و گاهی، در تاریک‌ترین لحظه‌هایش، آرزو می‌کرد جان را هرگز ملاقات نکرده بود، آرزو می‌کرد حقیقت را هرگز نیاموخته بود، آرزو می‌کرد در جهل راحتش مانده بود، آرزو می‌کرد برده‌ای خوشحال مانده بود."),
                    StoryParagraph("But such wishes were futile, such wishes were impossible, for once you have seen the truth, you cannot unsee it, once you have been awake, you cannot go back to sleep, once you have been free, you cannot return to slavery.", "اما چنین آرزوهایی بی‌فایده بودند، چنین آرزوهایی ناممکن بودند، زیرا وقتی حقیقت را دیده باشی، نمی‌توانی نبینی‌اش، وقتی بیدار بوده باشی، نمی‌توانی به خواب بازگردی، وقتی آزاد بوده باشی، نمی‌توانی به بردگی بازگردی."),
                    StoryParagraph("And so Bernard continued, continued to live, continued to suffer, continued to know, and in his suffering he found a strange kind of dignity, a strange kind of meaning, a strange kind of humanity.", "و اینگونه برنارد ادامه داد، به زندگی ادامه داد، به رنج کشیدن ادامه داد، به دانستن ادامه داد، و در رنجش نوعی عجیب از کرامت یافت، نوعی عجیب از معنا، نوعی عجیب از انسانیت."),
                    StoryParagraph("For suffering, he had learned, was the price of consciousness, was the price of freedom, was the price of being human, and it was a price worth paying, even if it meant being unhappy, even if it meant being alone, even if it meant being broken.", "زیرا رنج، آموخته بود، بهای آگاهی است، بهای آزادی است، بهای انسان بودن است، و بهایی بود که ارزش پرداختن داشت، حتی اگر به معنای ناخوشحال بودن بود، حتی اگر به معنای تنها بودن بود، حتی اگر به معنای شکسته بودن بود."),
                    StoryParagraph("And so ended the fifth part of the story of the Brave New World, with the fate of Bernard Marx, with the fate of a man who had seen the truth and who could not unsee it, with the fate of a man who had become human.", "و اینگونه بخش پنجم داستان دنیای قشنگ نو با سرنوشت برنارد مارکس، با سرنوشت مردی که حقیقت را دیده بود و نمی‌توانست نبینی‌اش، با سرنوشت مردی که انسان شده بود به پایان رسید.")
                )
            ),
            StoryChapter(
                number = 6, title = "The Meaning", titlePersian = "معنا",
                paragraphs = listOf(
                    StoryParagraph("And so the story of the Brave New World came to its end, or rather to its many ends, for there were many endings, the end of John, the end of Bernard, the end of Helmholtz, the end of everyone who had dared to be different.", "و اینگونه داستان دنیای قشنگ نو به پایانش رسید، یا بهتر به پایان‌های بسیاری، زیرا پایان‌های بسیاری بود، پایان جان، پایان برنارد، پایان هلمولتز، پایان هر کسی که جرات متفاوت بودن داشته بود."),
                    StoryParagraph("John had died, had killed himself, had been destroyed by the world that could not accept him, but in his death he had proven something, had proven that there was more to life than happiness, had proven that freedom was worth dying for.", "جان مرده بود، خودش را کشته بود، توسط جهانی که نمی‌توانست بپذیردش نابود شده بود، اما در مرگش چیزی را ثابت کرده بود، ثابت کرده بود زندگی بیشتر از خوشبختی است، ثابت کرده بود آزادی ارزش مردن دارد."),
                    StoryParagraph("Bernard had lived, had continued to live, had been forced to live in a world he could no longer believe in, but in his living he had proven something, had proven that it was possible to know the truth and to survive, had proven that consciousness was worth suffering for.", "برنارد زیسته بود، به زندگی ادامه داده بود، مجبور شده بود در جهانی زندگی کند که دیگر نمی‌توانست به آن باور داشته باشد، اما در زندگی‌اش چیزی را ثابت کرده بود، ثابت کرده بود ممکن است حقیقت را دانست و زنده ماند، ثابت کرده بود آگاهی ارزش رنج کشیدن دارد."),
                    StoryParagraph("Helmholtz had been exiled, had been sent away, had been given a chance to live among others who were different, but in his exile he had found something, had found a community, had found a place where he could be himself.", "هلمولتز تبعید شده بود، فرستاده شده بود، فرصتی یافته بود در میان دیگران متفاوت زندگی کند، اما در تبعیدش چیزی یافته بود، جامعه‌ای یافته بود، جایی یافته بود که می‌توانست خودش باشد."),
                    StoryParagraph("And so each of them, in their own way, had proven something about the human spirit, about the human capacity for resistance, about the human refusal to be enslaved, even when slavery was comfortable.", "و اینگونه هر یک از آنان، به شیوه خودش، چیزی درباره روح انسانی ثابت کرده بود، درباره توانایی انسانی برای مقاومت، درباره امتناع انسانی از به بردگی گرفته شدن، حتی وقتی بردگی راحت باشد."),
                    StoryParagraph("For the World State had achieved its goal, had achieved stability, had achieved happiness, had achieved the elimination of suffering, but it had achieved these things at a cost that was too high, at the cost of everything that made life worth living.", "زیرا دولت جهانی به هدفش رسیده بود، به ثبات رسیده بود، به خوشبختی رسیده بود، به حذف رنج رسیده بود، اما به این چیزها به بهایی رسیده بود که بسیار بالا بود، به بهای هر چیزی که زندگی را شایسته زندگی کردن می‌کند."),
                    StoryParagraph("It had eliminated art, eliminated literature, eliminated philosophy, eliminated religion, eliminated everything that required depth, that required struggle, that required suffering, that required freedom.", "هنر را حذف کرده بود، ادبیات را حذف کرده بود، فلسفه را حذف کرده بود، دین را حذف کرده بود، هر چیزی که عمق می‌خواست را حذف کرده بود، که مبارزه می‌خواست، که رنج می‌خواست، که آزادی می‌خواست."),
                    StoryParagraph("It had eliminated love, eliminated family, eliminated friendship, eliminated all the deep connections that made human beings human, and in their place it had put sex and soma and the endless distractions of a society that had no soul.", "عشق را حذف کرده بود، خانواده را حذف کرده بود، دوستی را حذف کرده بود، همه ارتباطات عمیقی که انسان‌ها را انسان می‌کند را حذف کرده بود، و در جایشان سکس و سوما و سرگرمی‌های بی‌پایان جامعه‌ای بی‌روح گذاشته بود."),
                    StoryParagraph("And this, perhaps, was the true horror of the Brave New World, not that it was cruel, but that it was kind, not that it made people suffer, but that it made them happy, not that it took away their freedom, but that it made them want to give it up.", "و این، شاید، وحشت واقعی دنیای قشنگ نو بود، نه اینکه بی‌رحم بود، بلکه اینکه مهربان بود، نه اینکه مردم را رنج می‌داد، بلکه اینکه خوشحالشان می‌کرد، نه اینکه آزادی‌شان را می‌گرفت، بلکه اینکه وادارشان می‌کرد بخواهند آن را بدهند."),
                    StoryParagraph("For it is one thing to be enslaved by force, to be chained and beaten and starved, to know that you are a slave and to hate it, to dream of freedom and to fight for it.", "زیرا یک چیز است که به زور به بردگی گرفته شوی، زنجیر و کتک و گرسنگی بکشی، بدانی برده‌ای و از آن متنفر باشی، در خواب آزادی را ببینی و برایش بجنگی."),
                    StoryParagraph("But it is quite another to be enslaved by pleasure, to be chained by comfort and fed by soma, to know that you are a slave and to love it, to have no dream of freedom because you have been conditioned to have no dreams.", "اما کاملاً چیز دیگری است که به‌واسطه لذت به بردگی گرفته شوی، به‌واسطه راحتی زنجیر شوی و با سوما تغذیه شوی، بدانی برده‌ای و دوستش بدار، هیچ خواب آزادی نداشته باشی چون شرطی شده‌ای که هیچ خوابی نداشته باشی."),
                    StoryParagraph("And this was the world that Huxley imagined, this was the world that he warned us about, this was the world that we must resist if we are to remain human, if we are to remain free, if we are to remain alive.", "و این جهانی بود که هاکسلی تصور کرد، این جهانی بود که از آن هشدار داد، این جهانی بود که باید در برابر آن مقاومت کنیم اگر می‌خواهیم انسان بمانیم، اگر می‌خواهیم آزاد بمانیم، اگر می‌خواهیم زنده بمانیم."),
                    StoryParagraph("For the Brave New World is not a place, not a time, not a society, but a temptation, a temptation that lies within each of us, a temptation to take the easy way, to choose comfort over truth, to choose happiness over freedom.", "زیرا دنیای قشنگ نو مکان نیست، زمان نیست، جامعه نیست، بلکه وسوسه‌ای است، وسوسه‌ای که در هر یک از ما جای دارد، وسوسه‌ای برای انتخاب راه آسان، برای انتخاب راحتی بر حقیقت، برای انتخاب خوشبختی بر آزادی."),
                    StoryParagraph("And the story of John, the story of Bernard, the story of Helmholtz, the story of the Brave New World, is a warning, a warning that we must not give in to this temptation, that we must not trade our freedom for security, that we must not trade our soul for comfort.", "و داستان جان، داستان برنارد، داستان هلمولتز، داستان دنیای قشنگ نو، هشداری است، هشداری که نباید تسلیم این وسوسه شویم، نباید آزادی‌مان را با امنیت معامله کنیم، نباید روح‌مان را با راحتی معامله کنیم."),
                    StoryParagraph("For in the end, the Brave New World is not a paradise, not a utopia, not a dream come true, but a nightmare disguised as a dream, a prison disguised as a paradise, a death disguised as life.", "زیرا در پایان، دنیای قشنگ نو بهشت نیست، آرمان‌شهر نیست، رؤیای محقق‌شده نیست، بلکه کابوسی است در لباس رؤیا، زندانی است در لباس بهشت، مرگی است در لباس زندگی."),
                    StoryParagraph("And Huxley, in writing this story, in imagining this world, in warning us about this future, was doing what all great writers do: he was showing us the truth about ourselves, the truth about the world, the truth about the choices we must make.", "و هاکسلی، در نوشتن این داستان، در تصور این جهان، در هشدار دادن به ما درباره این آینده، همان کاری را می‌کرد که همه نویسندگان بزرگ می‌کنند: حقیقت درباره خودمان را نشانمان می‌داد، حقیقت درباره جهان، حقیقت درباره انتخاب‌هایی که باید بکنیم."),
                    StoryParagraph("And so the story of the Brave New World came to its end, but the questions it raised, the questions about freedom and happiness, about truth and comfort, about what it means to be human, these questions remain.", "و اینگونه داستان دنیای قشنگ نو به پایانش رسید، اما پرسش‌هایی که مطرح کرد، پرسش‌هایی درباره آزادی و خوشبختی، درباره حقیقت و راحتی، درباره معنای انسان بودن، این پرسش‌ها باقی می‌مانند."),
                    StoryParagraph("They remain for us, for our time, for our world, for our future, for they are the questions that every generation must ask, the questions that every human being must confront, the questions that have no easy answers.", "برای ما باقی می‌مانند، برای زمان ما، برای جهان ما، برای آینده ما، زیرا پرسش‌هایی هستند که هر نسلی باید بپرسد، پرسش‌هایی که هر انسانی باید با آن‌ها روبرو شود، پرسش‌هایی که پاسخ آسان ندارند."),
                    StoryParagraph("And that, perhaps, is the meaning of the Brave New World, that the questions matter more than the answers, that the search matters more than the finding, that the freedom to ask matters more than the comfort of knowing.", "و این، شاید، معنای دنیای قشنگ نو است، که پرسش‌ها بیشتر از پاسخ‌ها مهم‌اند، که جستجو بیشتر از یافتن مهم است، که آزادی پرسیدن بیشتر از راحتی دانستن مهم است."),
                    StoryParagraph("And so the story ended, and the questions remained, and we, the readers, were left to find our own answers, to make our own choices, to live our own lives, to try to be human in a world that was always trying to make us something else.", "و اینگونه داستان تمام شد و پرسش‌ها باقی ماندند و ما، خوانندگان، ماندیم تا پاسخ‌های خودمان را بیابیم، انتخاب‌های خودمان را بکنیم، زندگی‌های خودمان را زندگی کنیم، تلاش کنیم انسان باشیم در جهانی که همیشه تلاش می‌کرد ما را چیز دیگری کند."),
                    StoryParagraph("The end.", "پایان."),
                    StoryParagraph("But the questions remain.", "اما پرسش‌ها باقی می‌مانند."),
                    StoryParagraph("And so ended the sixth and final part of the story of the Brave New World, not with an answer but with a question, not with a conclusion but with a beginning.", "و اینگونه بخش ششم و آخرین داستان دنیای قشنگ نو نه با پاسخ بلکه با پرسشی، نه با نتیجه‌گیری بلکه با آغازی به پایان رسید.")
                )
            )
        )
    )
}